INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anatomy-1', 'anatomy', 'Early doctors learned about human anatomy by studying the bodies of animals.', '早期的医生通过研究动物的身体来了解人体解剖学。', 'anatomy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('physiology-1', 'physiology', 'The study of physiology explains how different parts of the body work.', '生理学研究解释了身体各部分如何运作。', 'physiology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cell-1', 'cell', 'Every cell in the body contains a complete set of genes.', '体内每个细胞都含有一整套基因。', 'cell');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tissue-1', 'tissue', 'The drug is designed to repair damaged tissue in the muscles of the heart.', '这种药物旨在修复心肌中受损的组织。', 'tissue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('organ-1', 'organ', 'The liver is one of the largest organs in the human body.', '肝脏是人体最大的器官之一。', 'organs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skeleton-1', 'skeleton', 'The complete skeleton of a young woman was found near the old wall.', '在古墙附近发现了一具完整的年轻女性骨骼。', 'skeleton');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('muscle-1', 'muscle', 'Regular training helps to build muscle and improve general health.', '经常训练有助于增强肌肉、改善整体健康。', 'muscle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nerve-1', 'nerve', 'A damaged nerve may take many months to grow back.', '受损的神经可能需要数月才能长回来。', 'nerve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neuron-1', 'neuron', 'Each neuron in the brain can connect with thousands of others.', '大脑中的每个神经元都能与数千个其他神经元相连。', 'neuron');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spinal-cord-1', 'spinal-cord', 'The spinal cord carries messages between the brain and the rest of the body.', '脊髓在大脑和身体其他部位之间传递信息。', 'spinal cord');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artery-1', 'artery', 'A blocked artery can reduce the flow of blood to the heart.', '动脉堵塞可能减少流向心脏的血液。', 'artery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vein-1', 'vein', 'Blood returns to the heart through a vein after delivering oxygen.', '血液输送氧气后通过静脉回到心脏。', 'vein');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blood-vessel-1', 'blood-vessel', 'Smoking damages the walls of each blood vessel and raises the risk of illness.', '吸烟会损害血管壁,增加患病风险。', 'blood vessel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circulation-1', 'circulation', 'Regular walking can improve blood circulation in older people.', '经常散步可以改善老年人的血液循环。', 'circulation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circulation-2', 'circulation', 'The newspaper had a daily circulation of more than a million copies.', '这份报纸的日发行量超过一百万份。', 'circulation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('digestion-1', 'digestion', 'Fibre in the diet plays an important part in healthy digestion.', '饮食中的纤维对健康的消化起着重要作用。', 'digestion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('digestive-1', 'digestive', 'The digestive system breaks food down into substances the body can use.', '消化系统把食物分解成身体可以利用的物质。', 'digestive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('metabolism-1', 'metabolism', 'Metabolism tends to slow down as people get older.', '随着年龄增长,新陈代谢往往会减慢。', 'Metabolism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('respiratory-1', 'respiratory', 'Air pollution can lead to serious respiratory problems among children.', '空气污染可能导致儿童出现严重的呼吸问题。', 'respiratory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immune-system-1', 'immune-system', 'Lack of sleep can weaken the immune system over time.', '长期睡眠不足会削弱免疫系统。', 'immune system');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('immunity-1', 'immunity', 'Vaccines provide immunity against a number of dangerous diseases.', '疫苗能提供针对多种危险疾病的免疫力。', 'immunity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antibody-1', 'antibody', 'The body produces an antibody to fight each new infection.', '身体针对每种新的感染都会产生抗体。', 'antibody');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hormone-1', 'hormone', 'Stress causes the body to release a hormone called cortisol.', '压力使身体释放一种叫皮质醇的激素。', 'hormone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enzyme-1', 'enzyme', 'An enzyme in the stomach helps to break down protein.', '胃中的一种酶有助于分解蛋白质。', 'enzyme');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dna-1', 'dna', 'Scientists extracted DNA from the ancient bones found in the cave.', '科学家从洞穴中发现的古代骨骼里提取了 DNA。', 'DNA');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chromosome-1', 'chromosome', 'Humans normally have twenty-three pairs of chromosomes in each cell.', '人类每个细胞通常有二十三对染色体。', 'chromosomes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bacteria-1', 'bacteria', 'Some bacteria in the gut are essential for good health.', '肠道中的一些细菌对健康至关重要。', 'bacteria');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('virus-1', 'virus', 'The virus spreads through the air when an infected person coughs.', '感染者咳嗽时,病毒通过空气传播。', 'virus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('virus-2', 'virus', 'A computer virus damaged the hospital''s records and delayed treatment.', '一种计算机病毒损坏了医院的记录,延误了治疗。', 'virus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('microbe-1', 'microbe', 'A single spoonful of soil may contain millions of microbes.', '一小勺土壤可能含有数百万个微生物。', 'microbes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('germ-1', 'germ', 'Hand washing removes most of the germs that cause common illnesses.', '洗手能去除大部分导致常见疾病的病菌。', 'germs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pathogen-1', 'pathogen', 'A pathogen may pass from animals to humans through contact or food.', '病原体可能通过接触或食物从动物传给人类。', 'pathogen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disorder-1', 'disorder', 'Sleep disorders can have a serious effect on everyday life.', '睡眠障碍可能严重影响日常生活。', 'disorders');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chronic-1', 'chronic', 'Chronic back pain is one of the most common reasons for missing work.', '慢性背痛是请假最常见的原因之一。', 'Chronic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acute-1', 'acute', 'Patients with acute pain were treated immediately in the emergency room.', '急性疼痛的患者在急诊室立即得到治疗。', 'acute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acute-2', 'acute', 'Dogs have an acute sense of smell that can detect some diseases.', '狗有敏锐的嗅觉,能察觉某些疾病。', 'acute');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('epidemic-1', 'epidemic', 'A flu epidemic killed millions of people around the world in 1918.', '1918 年的流感疫情造成全球数百万人死亡。', 'epidemic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pandemic-1', 'pandemic', 'A pandemic affects people across many countries at the same time.', '大流行病会同时影响许多国家的人。', 'pandemic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('contagious-1', 'contagious', 'The illness is highly contagious and spreads easily through physical contact.', '这种疾病传染性极强,很容易通过身体接触传播。', 'contagious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infectious-1', 'infectious', 'Vaccines have greatly reduced deaths from infectious diseases.', '疫苗大大减少了传染病造成的死亡。', 'infectious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outbreak-1', 'outbreak', 'An outbreak of food poisoning closed several restaurants in the town.', '一场食物中毒事件的爆发导致镇上几家餐厅关闭。', 'outbreak');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diabetes-1', 'diabetes', 'Being overweight greatly increases the risk of developing diabetes.', '超重会大大增加患糖尿病的风险。', 'diabetes');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obesity-1', 'obesity', 'Rates of obesity among children have risen sharply in many countries.', '在许多国家,儿童肥胖率急剧上升。', 'obesity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tumour-1', 'tumour', 'Surgeons removed the tumour, and the patient made a full recovery.', '外科医生切除了肿瘤,患者完全康复了。', 'tumour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stroke-1', 'stroke', 'A stroke happens when the supply of blood to the brain is blocked.', '当大脑的血液供应被阻断时,就会发生中风。', 'stroke');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heart-attack-1', 'heart-attack', 'A healthy diet can reduce the risk of having a heart attack.', '健康饮食可以降低心脏病发作的风险。', 'heart attack');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blood-pressure-1', 'blood-pressure', 'High blood pressure often has no obvious symptoms in its early stages.', '高血压在早期通常没有明显症状。', 'blood pressure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cholesterol-1', 'cholesterol', 'Foods high in fat can raise the level of cholesterol in the blood.', '高脂肪食物可能升高血液中的胆固醇水平。', 'cholesterol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('asthma-1', 'asthma', 'Dust and pollution can make asthma much worse in young children.', '灰尘和污染可能使幼儿的哮喘严重恶化。', 'asthma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dementia-1', 'dementia', 'Older people with dementia may forget the names of close family members.', '患痴呆的老人可能会忘记亲人的名字。', 'dementia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alzheimers-disease-1', 'alzheimers-disease', 'Alzheimer''s disease gradually destroys memory and the ability to think clearly.', '阿尔茨海默病会逐渐破坏记忆和清晰思考的能力。', 'Alzheimer''s disease');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depression-1', 'depression', 'Regular exercise can reduce the symptoms of mild depression.', '经常运动可以减轻轻度抑郁症的症状。', 'depression');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depression-2', 'depression', 'Millions of people lost their jobs during the economic depression of the 1930s.', '20 世纪 30 年代的经济萧条期间,数百万人失业。', 'depression');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vaccine-1', 'vaccine', 'Researchers developed the new vaccine in less than a year.', '研究者用不到一年的时间研制出了这种新疫苗。', 'vaccine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antibiotic-1', 'antibiotic', 'Antibiotics do not work against illnesses caused by viruses.', '抗生素对病毒引起的疾病不起作用。', 'Antibiotics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drug-1', 'drug', 'The new drug is being tested on a small group of patients.', '这种新药正在一小组患者身上进行测试。', 'drug');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('medication-1', 'medication', 'Patients must take this medication every day for at least three months.', '患者必须每天服用这种药物,至少三个月。', 'medication');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dose-1', 'dose', 'A small dose of the drug is enough to relieve the pain.', '小剂量的这种药就足以缓解疼痛。', 'dose');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('side-effect-1', 'side-effect', 'A common side effect of the medicine is feeling tired during the day.', '这种药的一个常见副作用是白天感到疲倦。', 'side effect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('placebo-1', 'placebo', 'Half of the patients were given a placebo instead of the real drug.', '一半的患者服用的是安慰剂,而不是真正的药物。', 'placebo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clinical-trial-1', 'clinical-trial', 'The vaccine will enter a clinical trial with two thousand volunteers.', '这种疫苗将进入有两千名志愿者参加的临床试验。', 'clinical trial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cure-1', 'cure', 'There is still no cure for the common cold.', '普通感冒仍然没有治愈的方法。', 'cure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cure-2', 'cure', 'Doctors can now cure most people who develop this type of cancer.', '现在医生能够治愈大多数患这类癌症的人。', 'cure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heal-1', 'heal', 'Wounds heal more slowly in older people than in the young.', '老年人的伤口愈合得比年轻人慢。', 'heal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recover-1', 'recover', 'Most patients recover completely within two or three weeks.', '大多数患者在两三周内完全康复。', 'recover');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recovery-1', 'recovery', 'Good sleep plays an important part in recovery after an illness.', '良好的睡眠对病后康复起着重要作用。', 'recovery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rehabilitation-1', 'rehabilitation', 'Rehabilitation after a serious injury may take many months.', '重伤后的康复可能需要几个月。', 'Rehabilitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transplant-1', 'transplant', 'A heart transplant can give a seriously ill patient many more years of life.', '心脏移植能让重病患者多活很多年。', 'transplant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transplant-2', 'transplant', 'Surgeons can now transplant organs from one person to another safely.', '现在外科医生能够安全地把器官从一个人移植到另一个人身上。', 'transplant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anaesthetic-1', 'anaesthetic', 'The use of anaesthetic made surgery far less painful in the nineteenth century.', '十九世纪麻醉剂的使用大大减轻了手术的痛苦。', 'anaesthetic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genome-1', 'genome', 'The human genome contains around twenty thousand genes.', '人类基因组包含约两万个基因。', 'genome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('life-expectancy-1', 'life-expectancy', 'Life expectancy has risen steadily in most countries over the last century.', '过去一个世纪,大多数国家的预期寿命持续上升。', 'Life expectancy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mortality-1', 'mortality', 'Infant mortality fell sharply after clean water was introduced to the city.', '城市引入清洁水后,婴儿死亡率急剧下降。', 'mortality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('longevity-1', 'longevity', 'Diet and regular exercise appear to be linked to longevity.', '饮食和经常运动似乎与长寿有关。', 'longevity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hygiene-1', 'hygiene', 'Better hygiene in hospitals has greatly reduced the risk of infection.', '医院卫生条件的改善大大降低了感染风险。', 'hygiene');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sanitation-1', 'sanitation', 'Poor sanitation is a major cause of disease in crowded urban areas.', '卫生设施差是拥挤城区疾病的主要成因。', 'sanitation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('malnutrition-1', 'malnutrition', 'Malnutrition affects the physical and mental development of young children.', '营养不良影响幼儿的身心发育。', 'Malnutrition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deficiency-1', 'deficiency', 'A deficiency of vitamin C can cause serious problems with the gums.', '缺乏维生素 C 可能导致严重的牙龈问题。', 'deficiency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diet-1', 'diet', 'A diet rich in fruit and vegetables may help to prevent heart disease.', '富含水果和蔬菜的饮食可能有助于预防心脏病。', 'diet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sedentary-1', 'sedentary', 'A sedentary lifestyle is linked to a higher risk of many diseases.', '久坐的生活方式与多种疾病的较高风险有关。', 'sedentary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syndrome-1', 'syndrome', 'The syndrome causes extreme tiredness that can last for several months.', '这种综合征会引起持续数月的极度疲劳。', 'syndrome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hypertension-1', 'hypertension', 'Too much salt in the diet is one cause of hypertension.', '饮食中盐分过多是高血压的成因之一。', 'hypertension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('malaria-1', 'malaria', 'Malaria is spread by mosquitoes and remains a serious threat in Africa.', '疟疾由蚊子传播,在非洲仍是严重威胁。', 'Malaria');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infect-1', 'infect', 'The virus can infect people of all ages, but children suffer most.', '这种病毒能感染所有年龄段的人,但儿童受害最重。', 'infect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inject-1', 'inject', 'Doctors inject the vaccine into the upper part of the arm.', '医生把疫苗注射到上臂。', 'inject');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dissect-1', 'dissect', 'Medical students learn to dissect bodies in order to understand anatomy.', '医学生学习解剖遗体,以了解人体结构。', 'dissect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clot-1', 'clot', 'A blood clot in the leg can become dangerous if it moves to the lungs.', '腿部的血块如果移动到肺部,可能会很危险。', 'clot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paralysed-1', 'paralysed', 'He was left partly paralysed after the accident damaged his spine.', '事故损伤了他的脊柱,使他部分瘫痪。', 'paralysed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('malnourished-1', 'malnourished', 'Many of the children in the camp were seriously malnourished.', '营地里的许多孩子严重营养不良。', 'malnourished');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('handicap-1', 'handicap', 'Poor eyesight was once a serious handicap for people in many jobs.', '视力差曾是许多工作中的严重障碍。', 'handicap');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spleen-1', 'spleen', 'The spleen helps to filter the blood and fight infection.', '脾有助于过滤血液和抵抗感染。', 'spleen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('life-span-1', 'life-span', 'The average life-span of a wild fox is only about three years.', '野生狐狸的平均寿命只有大约三年。', 'life-span');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('death-rate-1', 'death-rate', 'The death rate from the disease fell after the vaccine was introduced.', '疫苗推出后,这种疾病的死亡率下降了。', 'death rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heart-rate-1', 'heart-rate', 'Your heart rate increases naturally when you take exercise.', '运动时心率会自然升高。', 'heart rate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('flesh-1', 'flesh', 'The bacteria spread quickly through the flesh of the infected animal.', '细菌在受感染动物的肌肉中迅速扩散。', 'flesh');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lung-1', 'lung', 'Smoking is the main cause of lung cancer in most countries.', '在大多数国家,吸烟是肺癌的主要成因。', 'lung');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('limb-1', 'limb', 'Some lizards can grow a new limb if one is lost.', '有些蜥蜴失去肢体后能再长出新的。', 'limb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('liver-1', 'liver', 'The liver removes harmful substances from the blood.', '肝脏清除血液中的有害物质。', 'liver');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gut-1', 'gut', 'The bacteria in the gut may affect both mood and weight.', '肠道中的细菌可能同时影响情绪和体重。', 'gut');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lump-1', 'lump', 'Doctors check any new lump carefully to see if it is dangerous.', '医生会仔细检查任何新出现的肿块,看看是否危险。', 'lump');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('strand-1', 'strand', 'A single strand of hair can provide a surprising amount of information.', '一根头发就能提供惊人的大量信息。', 'strand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('membrane-1', 'membrane', 'A thin membrane controls what enters and leaves each cell.', '一层薄膜控制着物质进出每个细胞。', 'membrane');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('complication-1', 'complication', 'Serious complications can occur if the infection is not treated quickly.', '如果感染不及时治疗,可能出现严重的并发症。', 'complications');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kidney-1', 'kidney', 'The kidneys remove waste from the blood and control the body''s water.', '肾脏清除血液中的废物,并调节体内水分。', 'kidneys');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incidence-1', 'incidence', 'The incidence of skin cancer is higher in sunny countries.', '阳光充足的国家皮肤癌的发病率更高。', 'incidence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('onset-1', 'onset', 'Exercise may delay the onset of memory problems in later life.', '运动可能推迟晚年记忆问题的发生。', 'onset');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bodily-1', 'bodily', 'Sweat helps to keep bodily temperature at a safe level.', '汗水有助于把体温保持在安全水平。', 'bodily');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('urine-1', 'urine', 'Doctors can test a patient''s urine to check for signs of diabetes.', '医生可以检测患者的尿液,查找糖尿病的迹象。', 'urine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('susceptible-1', 'susceptible', 'Elderly people are more susceptible to infection during the winter months.', '老年人在冬季更容易受到感染。', 'susceptible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sperm-1', 'sperm', 'A number of chemicals in the environment may reduce sperm counts in men.', '环境中的一些化学物质可能降低男性的精子数量。', 'sperm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hepatitis-1', 'hepatitis', 'Hepatitis is an illness that causes serious damage to the liver.', '肝炎是一种严重损害肝脏的疾病。', 'Hepatitis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chemotherapy-1', 'chemotherapy', 'Chemotherapy kills cancer cells but can also damage healthy ones.', '化疗能杀死癌细胞,但也可能损伤健康细胞。', 'Chemotherapy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('amino-acid-1', 'amino-acid', 'Proteins are made up of long chains of amino acids.', '蛋白质由长链氨基酸构成。', 'amino acids');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abdominal-1', 'abdominal', 'Common symptoms of the infection include fever and abdominal pain.', '这种感染的常见症状包括发烧和腹痛。', 'abdominal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marrow-1', 'marrow', 'New blood cells are constantly produced in the bone marrow.', '骨髓不断产生新的血细胞。', 'marrow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foetal-1', 'foetal', 'Smoking during pregnancy can seriously harm foetal development.', '孕期吸烟会严重损害胎儿发育。', 'foetal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cortex-1', 'cortex', 'The outer layer of the brain, called the cortex, controls thinking and language.', '大脑外层被称为皮层,控制思维和语言。', 'cortex');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('epidemiology-1', 'epidemiology', 'Epidemiology is the study of how diseases spread through populations.', '流行病学研究疾病如何在人群中传播。', 'Epidemiology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('helix-1', 'helix', 'Watson and Crick showed that DNA has the structure of a double helix.', '沃森和克里克证明了 DNA 具有双螺旋结构。', 'helix');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('splice-1', 'splice', 'Scientists can now splice genes from one organism into another.', '科学家现在可以把一种生物的基因拼接到另一种生物中。', 'splice');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capillary-1', 'capillary', 'Oxygen passes from the blood into the tissues through each tiny capillary.', '氧气通过每条微小的毛细血管从血液进入组织。', 'capillary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thumb-1', 'thumb', 'The human thumb allows us to hold and use tools with great skill.', '人的拇指使我们能灵巧地握持和使用工具。', 'thumb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plague-1', 'plague', 'The plague killed about a third of the population of Europe in the 1300s.', '14 世纪的瘟疫造成欧洲约三分之一人口死亡。', 'plague');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plague-2', 'plague', 'Rising costs continue to plague the national health service.', '不断上升的成本继续困扰着国家医疗服务体系。', 'plague');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lethal-1', 'lethal', 'Even a small amount of this poison can be lethal to humans.', '即使少量这种毒药也可能对人类致命。', 'lethal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gland-1', 'gland', 'The gland in the neck controls the speed of the body''s metabolism.', '颈部的这个腺体控制着身体新陈代谢的速度。', 'gland');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bowel-1', 'bowel', 'A diet high in fibre may reduce the risk of bowel cancer.', '高纤维饮食可能降低肠癌风险。', 'bowel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cavity-1', 'cavity', 'Sugar helps bacteria to create a cavity in a tooth.', '糖会促使细菌在牙齿上形成蛀洞。', 'cavity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('swallow-1', 'swallow', 'Older patients sometimes find it difficult to swallow large tablets.', '老年患者有时很难吞咽大药片。', 'swallow');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('psychology-1', 'psychology', 'Studies in psychology show that people often copy those around them.', '心理学研究表明,人们常常模仿周围的人。', 'psychology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('psychologist-1', 'psychologist', 'The psychologist asked children to wait alone before eating a sweet.', '这位心理学家让孩子们独自等待一段时间再吃糖。', 'psychologist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cognitive-1', 'cognitive', 'Learning a second language may improve certain cognitive skills.', '学习第二语言可能提高某些认知能力。', 'cognitive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cognition-1', 'cognition', 'Poor sleep has a clear effect on cognition in older adults.', '睡眠不足对老年人的认知有明显影响。', 'cognition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perception-1', 'perception', 'The colour of food can change our perception of its taste.', '食物的颜色会改变我们对味道的感知。', 'perception');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perception-2', 'perception', 'Public perception of the risk has changed since the accident.', '事故发生后,公众对这一风险的看法有所改变。', 'perception');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sensory-1', 'sensory', 'Babies receive a great deal of sensory information from the world around them.', '婴儿从周围世界接收大量感官信息。', 'sensory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('memory-1', 'memory', 'Regular sleep helps to strengthen long-term memory in adults.', '规律睡眠有助于增强成年人的长期记忆。', 'memory');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recall-1', 'recall', 'Participants were asked to recall as many words as possible from the list.', '参与者被要求尽可能多地回忆起列表中的单词。', 'recall');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('retrieve-1', 'retrieve', 'The brain may find it harder to retrieve information as we age.', '随着年龄增长,大脑提取信息可能变得更难。', 'retrieve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intelligence-1', 'intelligence', 'Early tests of intelligence were criticised for being unfair to certain groups.', '早期的智力测试因对某些群体不公平而受到批评。', 'intelligence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('iq-1', 'iq', 'A high IQ does not guarantee success in later life.', '高智商并不能保证日后的成功。', 'IQ');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intuition-1', 'intuition', 'Experienced doctors often rely on intuition when making quick decisions.', '有经验的医生在快速决策时常常依靠直觉。', 'intuition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consciousness-1', 'consciousness', 'Scientists still do not fully understand how the brain produces consciousness.', '科学家仍未完全理解大脑如何产生意识。', 'consciousness');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subconscious-1', 'subconscious', 'Subconscious memories may influence the choices people make without their realising it.', '潜意识中的记忆可能在不知不觉中影响人们的选择。', 'Subconscious');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emotion-1', 'emotion', 'Music can produce strong emotion even in very young children.', '音乐甚至能让很小的孩子产生强烈的情感。', 'emotion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emotional-1', 'emotional', 'Family support is important for the emotional health of teenagers.', '家庭支持对青少年的情感健康很重要。', 'emotional');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mood-1', 'mood', 'Bright sunlight has a positive effect on mood for most people.', '对大多数人来说,明媚的阳光对心情有积极影响。', 'mood');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anxiety-1', 'anxiety', 'Many students suffer from anxiety in the weeks before an exam.', '许多学生在考前几周感到焦虑。', 'anxiety');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stress-1', 'stress', 'Long working hours are a major cause of stress among office staff.', '长时间工作是办公室员工压力的主要来源。', 'stress');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trauma-1', 'trauma', 'Survivors of the earthquake may suffer from trauma for many years.', '地震幸存者可能多年遭受心理创伤。', 'trauma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phobia-1', 'phobia', 'A phobia of spiders can be treated through gradual exposure.', '蜘蛛恐惧症可以通过逐步接触来治疗。', 'phobia');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('personality-1', 'personality', 'Twin studies suggest that genes play a role in shaping personality.', '双胞胎研究表明,基因在塑造个性方面起着作用。', 'personality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temperament-1', 'temperament', 'Babies show differences in temperament from the first weeks of life.', '婴儿从出生头几周起就表现出性情上的差异。', 'temperament');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motivation-1', 'motivation', 'Students with strong motivation tend to perform better at school.', '动机强的学生往往在学校表现更好。', 'motivation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('incentive-1', 'incentive', 'Lower taxes provide an incentive for companies to invest in clean energy.', '减税激励公司投资清洁能源。', 'incentive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reward-1', 'reward', 'Animals learn more quickly when they receive a reward for correct behaviour.', '动物因正确行为得到奖励时学得更快。', 'reward');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('punishment-1', 'punishment', 'Experts believe that physical punishment does little to improve behaviour.', '专家认为体罚对改善行为几乎没有帮助。', 'punishment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('habit-1', 'habit', 'It takes several weeks of practice to form a new habit.', '养成一个新习惯需要几周的练习。', 'habit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('attention-1', 'attention', 'Young children can pay attention to a single task for only a short time.', '幼儿只能在短时间内把注意力集中在一项任务上。', 'attention');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concentration-1', 'concentration', 'Loud noise can seriously affect concentration in the classroom.', '巨大的噪音可能严重影响课堂上的专注力。', 'concentration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concentration-2', 'concentration', 'The concentration of carbon dioxide in the air continues to rise.', '空气中二氧化碳的浓度继续上升。', 'concentration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('distraction-1', 'distraction', 'Mobile phones are a major distraction for students during lessons.', '手机是学生上课时的主要分心来源。', 'distraction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multitasking-1', 'multitasking', 'Research suggests that multitasking reduces the quality of people''s work.', '研究表明,多任务处理会降低工作质量。', 'multitasking');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decision-making-1', 'decision-making', 'Lack of sleep has a negative effect on decision-making.', '睡眠不足对决策有负面影响。', 'decision-making');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reasoning-1', 'reasoning', 'Children develop the ability to use logical reasoning at about the age of seven.', '儿童大约在七岁时发展出运用逻辑推理的能力。', 'reasoning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('judgement-1', 'judgement', 'Tiredness affects judgement and increases the risk of road accidents.', '疲劳影响判断力,增加交通事故风险。', 'judgement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stimulus-1', 'stimulus', 'The rats quickly learned to respond to the new stimulus.', '老鼠很快学会了对新的刺激作出反应。', 'stimulus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('response-1', 'response', 'Participants'' response to the images was measured using brain scans.', '参与者对图像的反应通过脑部扫描测量。', 'response');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reflex-1', 'reflex', 'Pulling your hand away from something hot is a natural reflex.', '把手从烫的东西上缩回是一种自然反射。', 'reflex');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conditioning-1', 'conditioning', 'Pavlov''s work on conditioning showed that dogs could learn to expect food.', '巴甫洛夫关于条件反射的研究表明,狗能学会期待食物。', 'conditioning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infant-1', 'infant', 'An infant can recognise its mother''s voice within days of birth.', '婴儿出生几天内就能辨认出母亲的声音。', 'infant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('toddler-1', 'toddler', 'A toddler may learn several new words every single day.', '学步儿童每天可能学会几个新词。', 'toddler');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adolescent-1', 'adolescent', 'Most adolescents need more sleep than either children or adults.', '大多数青少年比儿童和成年人都需要更多睡眠。', 'adolescents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adolescence-1', 'adolescence', 'The brain continues to change in important ways during adolescence.', '在青春期,大脑继续发生重要变化。', 'adolescence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peer-1', 'peer', 'Young children often learn new skills by watching their peers.', '幼儿常常通过观察同龄人学习新技能。', 'peers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peer-pressure-1', 'peer-pressure', 'Peer pressure is one of the main reasons why teenagers start smoking.', '同伴压力是青少年开始吸烟的主要原因之一。', 'Peer pressure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('self-esteem-1', 'self-esteem', 'Praise from teachers can help to build self-esteem in young children.', '老师的表扬有助于增强幼儿的自尊。', 'self-esteem');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confidence-1', 'confidence', 'Learning a musical instrument can give children greater confidence.', '学习乐器能让孩子更加自信。', 'confidence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('confidence-2', 'confidence', 'Public confidence in the health system fell after the scandal.', '丑闻发生后,公众对医疗系统的信任下降了。', 'confidence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('empathy-1', 'empathy', 'Reading novels may help children to develop empathy towards others.', '读小说可能有助于孩子培养对他人的同理心。', 'empathy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('altruism-1', 'altruism', 'Some birds show altruism by helping to raise the young of others.', '有些鸟表现出利他行为,帮助抚养其他鸟的幼鸟。', 'altruism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('introvert-1', 'introvert', 'An introvert usually prefers quiet activities to large social events.', '内向者通常更喜欢安静的活动,而不是大型社交活动。', 'introvert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('extrovert-1', 'extrovert', 'An extrovert tends to gain energy from being around other people.', '外向者往往从与他人相处中获得能量。', 'extrovert');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('creativity-1', 'creativity', 'Schools can encourage creativity by allowing more time for art and play.', '学校可以留出更多时间给艺术和游戏,以鼓励创造力。', 'creativity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imagination-1', 'imagination', 'Reading stories helps to develop the imagination of young children.', '读故事有助于培养幼儿的想象力。', 'imagination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nature-versus-nurture-1', 'nature-versus-nurture', 'The debate on nature versus nurture has continued for more than a century.', '关于先天与后天的争论已持续了一个多世纪。', 'nature versus nurture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('placebo-effect-1', 'placebo-effect', 'The placebo effect shows that people''s beliefs can influence their recovery.', '安慰剂效应表明,人的信念能影响康复。', 'placebo effect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('well-being-1', 'well-being', 'Spending time outdoors can improve people''s general sense of well-being.', '在户外活动可以提升人们整体的幸福感。', 'well-being');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intellect-1', 'intellect', 'The author believed that a good education could develop the intellect of any child.', '作者认为,良好的教育能发展任何孩子的才智。', 'intellect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rational-1', 'rational', 'Economists once assumed that consumers always made rational choices.', '经济学家曾假定消费者总会作出理性的选择。', 'rational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('impulsive-1', 'impulsive', 'Teenagers can be more impulsive than adults because their brains are still developing.', '青少年可能比成年人更冲动,因为他们的大脑仍在发育。', 'impulsive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('egocentric-1', 'egocentric', 'Very young children are naturally egocentric and find it hard to share.', '很小的孩子天生以自我为中心,很难与人分享。', 'egocentric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('engrossed-1', 'engrossed', 'The children were so engrossed in the game that they did not hear the bell.', '孩子们全神贯注地玩游戏,连铃声都没听到。', 'engrossed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('desire-1', 'desire', 'The desire for social approval influences much of our behaviour.', '渴望得到社会认可影响着我们的许多行为。', 'desire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('passion-1', 'passion', 'Her passion for science began when she was given a telescope as a child.', '她对科学的激情始于童年时得到的一架望远镜。', 'passion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obedience-1', 'obedience', 'A famous experiment on obedience shocked the public in the 1960s.', '20 世纪 60 年代,一项著名的服从实验震惊了公众。', 'obedience');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dissonance-1', 'dissonance', 'Cognitive dissonance occurs when people''s actions conflict with their beliefs.', '当人们的行为与信念冲突时,就会出现认知失调。', 'dissonance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('body-language-1', 'body-language', 'Body language can reveal what people really feel about each other.', '肢体语言能透露人们对彼此的真实感受。', 'Body language');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('social-interaction-1', 'social-interaction', 'Babies need plenty of social interaction in order to develop normally.', '婴儿需要大量社会交往才能正常发育。', 'social interaction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('behavioural-1', 'behavioural', 'Behavioural changes are often the first sign of the illness.', '行为变化往往是这种疾病的最初迹象。', 'Behavioural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cue-1', 'cue', 'Babies use visual cues to work out what adults are feeling.', '婴儿利用视觉提示来判断成年人的感受。', 'cues');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('psychiatric-1', 'psychiatric', 'Many patients with psychiatric problems also suffer from poor physical health.', '许多有精神问题的患者身体健康状况也较差。', 'psychiatric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encode-1', 'encode', 'The brain may encode new information more effectively during periods of rest.', '大脑在休息时也许能更有效地编码新信息。', 'encode');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('innate-1', 'innate', 'Some psychologists argue that the ability to learn language is innate.', '一些心理学家认为,学习语言的能力是天生的。', 'innate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('volition-1', 'volition', 'Participants took part of their own volition and could leave at any time.', '参与者是自愿参加的,可以随时退出。', 'volition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fantasy-1', 'fantasy', 'Young children often find it difficult to separate fantasy from reality.', '幼儿常常很难区分幻想和现实。', 'fantasy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nightmare-1', 'nightmare', 'Stress and anxiety can increase the frequency of a person''s nightmares.', '压力和焦虑可能增加一个人做噩梦的频率。', 'nightmares');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('panic-1', 'panic', 'News of the disease caused panic across the country.', '这种疾病的消息引起了全国恐慌。', 'panic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('panic-2', 'panic', 'People tend to panic when they do not have clear information.', '人们在没有明确信息时容易恐慌。', 'panic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obsession-1', 'obsession', 'The modern obsession with thinness can damage young people''s health.', '现代人对瘦的痴迷可能损害年轻人的健康。', 'obsession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apprehension-1', 'apprehension', 'Many patients feel some apprehension before a major operation.', '许多患者在大手术前会感到一些忧虑。', 'apprehension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mentality-1', 'mentality', 'Changing the mentality of a whole industry can take many years.', '改变整个行业的思维方式可能需要很多年。', 'mentality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('linguistics-1', 'linguistics', 'Students of linguistics examine how languages change over long periods of time.', '学习语言学的学生研究语言如何长期演变。', 'linguistics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('linguist-1', 'linguist', 'The linguist spent ten years recording the speech of older villagers.', '这位语言学家花了十年时间记录老年村民的话语。', 'linguist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('linguistic-1', 'linguistic', 'Linguistic differences between the two regions have grown over the past century.', '过去一个世纪,这两个地区的语言差异越来越大。', 'Linguistic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vocabulary-1', 'vocabulary', 'Children who read often tend to have a much larger vocabulary.', '经常阅读的孩子往往词汇量更大。', 'vocabulary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grammar-1', 'grammar', 'The grammar of the language is quite simple, but its sounds are difficult.', '这种语言的语法相当简单,但发音很难。', 'grammar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syntax-1', 'syntax', 'The syntax of English has changed relatively little in the past few centuries.', '过去几个世纪,英语的句法变化相对较小。', 'syntax');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('semantic-1', 'semantic', 'Semantic changes mean that some words now have the opposite of their original meaning.', '语义的变化意味着一些词现在的含义与原义相反。', 'Semantic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phonetics-1', 'phonetics', 'Phonetics is the study of how the sounds of speech are produced.', '语音学研究语音是如何发出的。', 'Phonetics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pronunciation-1', 'pronunciation', 'The pronunciation of many English words has changed since Shakespeare''s time.', '自莎士比亚时代以来,许多英语单词的发音都发生了变化。', 'pronunciation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accent-1', 'accent', 'Listeners often make quick judgements about people based on their accent.', '听者常常根据口音对人作出快速判断。', 'accent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dialect-1', 'dialect', 'Each valley in the region once had its own distinct dialect.', '该地区的每个山谷都曾有自己独特的方言。', 'dialect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mother-tongue-1', 'mother-tongue', 'Children usually learn to read more easily in their mother tongue.', '孩子通常用母语学习阅读更容易。', 'mother tongue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('native-speaker-1', 'native-speaker', 'Even a native speaker may find this ancient text hard to understand.', '即使是母语者,也可能觉得这篇古文难以理解。', 'native speaker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bilingual-1', 'bilingual', 'Bilingual children can often switch between languages with little effort.', '双语儿童常常能毫不费力地在两种语言之间切换。', 'Bilingual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multilingual-1', 'multilingual', 'In this multilingual society, most people use at least three languages daily.', '在这个多语社会中,大多数人每天至少使用三种语言。', 'multilingual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fluent-1', 'fluent', 'It usually takes several years to become fluent in a foreign language.', '要流利地掌握一门外语,通常需要好几年。', 'fluent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fluency-1', 'fluency', 'Regular conversation with others is the best way to develop fluency.', '经常与人交谈是提高流利度的最好方法。', 'fluency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('literacy-1', 'literacy', 'Rates of literacy rose quickly after free schools were introduced.', '免费学校推行后,识字率迅速上升。', 'literacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('illiterate-1', 'illiterate', 'In the Middle Ages, most ordinary people in Europe were illiterate.', '中世纪时,欧洲大多数普通人都是文盲。', 'illiterate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('alphabet-1', 'alphabet', 'The modern English alphabet developed from a much older Roman one.', '现代英语字母表由更古老的罗马字母发展而来。', 'alphabet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('script-1', 'script', 'The ancient script has never been fully understood by modern scholars.', '现代学者从未完全读懂这种古代文字。', 'script');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('script-2', 'script', 'The actor forgot part of the script during the first performance.', '首场演出时,这位演员忘了部分剧本。', 'script');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('symbol-1', 'symbol', 'Early farmers used a simple symbol to represent each type of grain.', '早期农民用简单的符号表示每种谷物。', 'symbol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gesture-1', 'gesture', 'A simple gesture can have very different meanings in different cultures.', '一个简单的手势在不同文化中可能有截然不同的含义。', 'gesture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sign-language-1', 'sign-language', 'Deaf children learn sign language as naturally as others learn to speak.', '聋儿学习手语就像其他孩子学说话一样自然。', 'sign language');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acquisition-1', 'acquisition', 'The acquisition of a first language happens without formal teaching.', '第一语言的习得不需要正规教学。', 'acquisition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('acquisition-2', 'acquisition', 'The company''s acquisition of a smaller rival made it the largest in Europe.', '这家公司收购了一家较小的竞争对手,成为欧洲最大的公司。', 'acquisition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('translate-1', 'translate', 'Some poems are almost impossible to translate into another language.', '有些诗歌几乎无法翻译成另一种语言。', 'translate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('translation-1', 'translation', 'An English translation of the text appeared more than a century later.', '这篇文本的英译本在一个多世纪后才问世。', 'translation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interpreter-1', 'interpreter', 'An interpreter was needed for the meeting between the two leaders.', '两国领导人会晤时需要一名口译员。', 'interpreter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('verbal-1', 'verbal', 'Verbal skills develop rapidly between the ages of two and five.', '语言能力在两岁到五岁之间迅速发展。', 'Verbal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('non-verbal-1', 'non-verbal', 'Non-verbal communication includes facial expressions and the way people stand.', '非言语交流包括面部表情和人们的站姿。', 'Non-verbal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('oral-1', 'oral', 'These stories were passed down through oral tradition for many generations.', '这些故事通过口头传统流传了许多代。', 'oral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('written-1', 'written', 'No written records of the language survive from before the tenth century.', '这种语言没有十世纪以前的书面记录留存下来。', 'written');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('idiom-1', 'idiom', 'Learners often find it difficult to understand an idiom such as ''break the ice''.', '学习者常常觉得 “break the ice” 这样的习语很难理解。', 'idiom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('etymology-1', 'etymology', 'The etymology of the word shows that it came from ancient Greek.', '这个词的词源显示它来自古希腊语。', 'etymology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endangered-language-1', 'endangered-language', 'Researchers are making recordings of each endangered language before it disappears.', '研究者正在为每种濒危语言录音,以防它们消失。', 'endangered language');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lingua-franca-1', 'lingua-franca', 'Latin served as a lingua franca for educated people across Europe.', '拉丁语曾是欧洲各地受教育者的通用语。', 'lingua franca');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('phonology-1', 'phonology', 'The phonology of the language includes several sounds not found in English.', '这种语言的音系包括几种英语中没有的音。', 'phonology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tense-1', 'tense', 'Some languages have no verb forms to show past or future tense.', '有些语言没有表示过去或将来时态的动词形式。', 'tense');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tense-2', 'tense', 'Relations between the two countries remained tense for several years.', '两国关系多年来一直紧张。', 'tense');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('verse-1', 'verse', 'Many early histories were written in verse so that they could be remembered.', '许多早期历史用韵文写成,以便记忆。', 'verse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fable-1', 'fable', 'The ancient fable teaches children the value of hard work.', '这则古老的寓言教导孩子们勤劳的价值。', 'fable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('maxim-1', 'maxim', 'The old maxim that practice makes perfect has some scientific support.', '“熟能生巧”这句老格言有一定的科学依据。', 'maxim');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('adage-1', 'adage', 'According to an old adage, a picture is worth a thousand words.', '有句古老的谚语说,一图胜千言。', 'adage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('satire-1', 'satire', 'The novel is a clever satire on the politics of the period.', '这部小说是对当时政治的巧妙讽刺。', 'satire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('farce-1', 'farce', 'The play is a farce about a family who keep losing their money.', '这部戏是一出闹剧,讲的是一个总是丢钱的家庭。', 'farce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pictograph-1', 'pictograph', 'A pictograph uses a simple picture to represent an object or an idea.', '象形文字用简单的图画表示物体或概念。', 'pictograph');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abstraction-1', 'abstraction', 'Mathematics requires a high level of abstraction from everyday experience.', '数学需要从日常经验中进行高度抽象。', 'abstraction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coin-1', 'coin', 'Writers often coin new words to describe recent technologies.', '作家常常创造新词来描述新技术。', 'coin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coin-2', 'coin', 'A Roman coin was found among the remains of the old house.', '在这座老房子的遗迹中发现了一枚罗马硬币。', 'coin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cogent-1', 'cogent', 'The report presents a cogent argument for reforming the education system.', '这份报告为改革教育体系提出了令人信服的论证。', 'cogent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('persuasive-1', 'persuasive', 'The speaker gave a persuasive account of the benefits of learning languages.', '演讲者很有说服力地阐述了学习语言的好处。', 'persuasive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('orator-1', 'orator', 'Cicero was a famous Roman orator whose speeches are still studied today.', '西塞罗是著名的罗马演说家,他的演讲至今仍有人研究。', 'orator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('discourse-1', 'discourse', 'Scientific discourse has become increasingly dominated by the English language.', '科学话语越来越被英语主导。', 'discourse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rhetoric-1', 'rhetoric', 'Students in ancient Greece studied rhetoric to prepare for public life.', '古希腊的学生学习修辞,为公共生活做准备。', 'rhetoric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('metaphor-1', 'metaphor', 'The author uses the metaphor of a journey to describe language learning.', '作者用旅程这一隐喻来描述语言学习。', 'metaphor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('usage-1', 'usage', 'The usage of this word has changed greatly over the past fifty years.', '过去五十年,这个词的用法发生了很大变化。', 'usage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('articulate-1', 'articulate', 'Young children may struggle to articulate their feelings clearly.', '幼儿可能难以清楚表达自己的感受。', 'articulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('articulate-2', 'articulate', 'She was an articulate speaker who could explain difficult ideas simply.', '她善于表达,能把难懂的观点解释得很简单。', 'articulate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('utterance-1', 'utterance', 'A child''s first utterance usually consists of just a single word.', '孩子最初的话语通常只有一个词。', 'utterance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lexical-1', 'lexical', 'The study compared lexical differences between British and American English.', '这项研究比较了英式英语和美式英语的词汇差异。', 'lexical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('grammatical-1', 'grammatical', 'Young children make grammatical errors that follow surprisingly regular patterns.', '幼儿犯的语法错误遵循着惊人的规律。', 'grammatical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('denote-1', 'denote', 'Different colours on the map denote different language families.', '地图上不同的颜色表示不同的语系。', 'denote');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syllable-1', 'syllable', 'Japanese words are built from short units that are similar to a syllable.', '日语单词由类似音节的短单位构成。', 'syllable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('syntactic-1', 'syntactic', 'Syntactic rules determine the order of words in a sentence.', '句法规则决定句子中的词序。', 'Syntactic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transcription-1', 'transcription', 'The transcription of the interviews took the researchers several months.', '研究者花了几个月才把访谈转写完。', 'transcription');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vowel-1', 'vowel', 'Hawaiian has only five vowels and a small number of other sounds.', '夏威夷语只有五个元音和少量其他音。', 'vowels');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corpus-1', 'corpus', 'Researchers used a large corpus of newspaper texts to study word frequency.', '研究者利用大型报纸语料库研究词频。', 'corpus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('derivative-1', 'derivative', 'The word ''happiness'' is a derivative of the adjective ''happy''.', '“happiness” 一词是形容词 “happy” 的派生词。', 'derivative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('singular-1', 'singular', 'Some nouns have the same form in the singular as in the plural.', '有些名词的单数和复数形式相同。', 'singular');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transcribe-1', 'transcribe', 'Monks spent years transcribing old books by hand in the Middle Ages.', '中世纪时,修道士花费多年时间手抄古书。', 'transcribing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('connotation-1', 'connotation', 'The word ''cheap'' often has a negative connotation for English speakers.', '对说英语的人来说,“cheap” 一词往往带有负面的含义。', 'connotation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('comma-1', 'comma', 'A misplaced comma can sometimes change the meaning of a legal document.', '一个放错位置的逗号有时会改变法律文件的含义。', 'comma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consonant-1', 'consonant', 'Some languages have long groups of consonants that are hard to pronounce.', '有些语言有一长串难以发音的辅音。', 'consonants');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('plural-1', 'plural', 'In some languages, the plural is shown by repeating the word.', '在一些语言中,复数通过重复单词来表示。', 'plural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unintelligible-1', 'unintelligible', 'Old English is now unintelligible to most modern speakers.', '现代大多数说英语的人已经无法理解古英语。', 'unintelligible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('descriptor-1', 'descriptor', 'The test uses a clear descriptor for each level of ability.', '这项测试对每个能力水平都有明确的描述词。', 'descriptor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('narrative-1', 'narrative', 'The early chapters provide a clear narrative of the voyage.', '开头几章对这次航行作了清晰的叙述。', 'narrative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('narrator-1', 'narrator', 'The narrator of the novel is a young girl living in the countryside.', '这部小说的叙述者是住在乡下的小女孩。', 'narrator');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tone-1', 'tone', 'The tone of the letter suggests that the author was deeply worried.', '这封信的语气表明作者非常担忧。', 'tone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('archaeology-1', 'archaeology', 'Advances in archaeology have changed our view of how early towns developed.', '考古学的进步改变了我们对早期城镇发展的看法。', 'archaeology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('archaeologist-1', 'archaeologist', 'An archaeologist discovered the remains of a Roman villa beneath the farm.', '一位考古学家在农场下面发现了一座罗马别墅的遗迹。', 'archaeologist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excavate-1', 'excavate', 'Teams from three universities will excavate the site next summer.', '三所大学的团队明年夏天将发掘这处遗址。', 'excavate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('excavation-1', 'excavation', 'Excavation of the ancient city began in the early twentieth century.', '这座古城的发掘始于二十世纪初。', 'Excavation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artefact-1', 'artefact', 'Each artefact was carefully cleaned and photographed before being moved.', '每件人工制品在移动前都经过仔细清理和拍照。', 'artefact');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('relic-1', 'relic', 'The old stone bridge is a relic of the town''s Roman past.', '这座古石桥是该镇罗马时代的遗物。', 'relic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remains-1', 'remains', 'The remains of an ancient ship were found beneath the river mud.', '在河底的淤泥下发现了一艘古船的遗骸。', 'remains');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ruins-1', 'ruins', 'Tourists come from around the world to visit the ruins of the temple.', '游客从世界各地前来参观神庙的废墟。', 'ruins');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('site-1', 'site', 'Archaeologists found thousands of stone tools at the site.', '考古学家在这处遗址发现了数千件石器。', 'site');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tomb-1', 'tomb', 'The tomb contained gold jewellery and food for the next life.', '墓中有金首饰和为来世准备的食物。', 'tomb');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pyramid-1', 'pyramid', 'Thousands of workers were needed to build each pyramid in Egypt.', '在埃及,建造每座金字塔都需要数千名工人。', 'pyramid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inscription-1', 'inscription', 'An inscription on the stone records the name of the local ruler.', '石头上的铭文记录了当地统治者的名字。', 'inscription');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hieroglyph-1', 'hieroglyph', 'Each hieroglyph could represent either a sound or a complete idea.', '每个象形文字既可以表示一个音,也可以表示一个完整的概念。', 'hieroglyph');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carbon-dating-1', 'carbon-dating', 'Carbon dating showed that the wooden tools were about six thousand years old.', '碳定年显示这些木制工具约有六千年历史。', 'Carbon dating');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prehistoric-1', 'prehistoric', 'Prehistoric people painted animals on the walls of the caves.', '史前人类在洞穴的墙壁上画动物。', 'Prehistoric');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stone-age-1', 'stone-age', 'People in the Stone Age made sharp tools from a type of hard rock.', '石器时代的人用一种坚硬的岩石制作锋利的工具。', 'Stone Age');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bronze-age-1', 'bronze-age', 'Trade across the region grew rapidly during the Bronze Age.', '青铜时代,这一地区的贸易迅速发展。', 'Bronze Age');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('iron-age-1', 'iron-age', 'Iron Age farmers built round houses from wood and dried mud.', '铁器时代的农民用木头和干泥建造圆屋。', 'Iron Age');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('medieval-1', 'medieval', 'The medieval town still has its original walls and narrow streets.', '这座中世纪小镇仍保留着原有的城墙和狭窄的街道。', 'medieval');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ancient-1', 'ancient', 'Ancient Egyptians used papyrus plants to make an early type of paper.', '古埃及人用纸莎草制造一种早期的纸。', 'Ancient');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antique-1', 'antique', 'The museum bought the antique clock from a private collector.', '博物馆从一位私人收藏家手中买下了这座古董钟。', 'antique');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('civilisation-1', 'civilisation', 'The Maya civilisation developed a sophisticated calendar and system of writing.', '玛雅文明发展出了精密的历法和文字系统。', 'civilisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dynasty-1', 'dynasty', 'The dynasty ruled the country for more than three hundred years.', '这个朝代统治该国三百多年。', 'dynasty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('empire-1', 'empire', 'At its height, the Roman Empire stretched from Britain to Egypt.', '罗马帝国全盛时期从不列颠延伸到埃及。', 'Empire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('emperor-1', 'emperor', 'The emperor ordered the construction of a great wall along the border.', '皇帝下令沿边境修建一道长城。', 'emperor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monarch-1', 'monarch', 'Queen Victoria was one of the longest-reigning monarchs in British history.', '维多利亚女王是英国历史上在位时间最长的君主之一。', 'monarchs');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monarchy-1', 'monarchy', 'The monarchy lost most of its political power during the nineteenth century.', '十九世纪,君主制失去了大部分政治权力。', 'monarchy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reign-1', 'reign', 'Trade and the arts flourished during the reign of the young queen.', '在这位年轻女王统治期间,贸易和艺术蓬勃发展。', 'reign');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reign-2', 'reign', 'The king reigned for over fifty years and left a stable country.', '这位国王统治了五十多年,留下了一个稳定的国家。', 'reigned');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('kingdom-1', 'kingdom', 'The small kingdom grew wealthy by controlling trade on the river.', '这个小王国通过控制河上贸易而富裕起来。', 'kingdom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aristocracy-1', 'aristocracy', 'Land ownership allowed the aristocracy to keep its political power for centuries.', '贵族阶层凭借土地所有权,掌握政治权力长达数百年。', 'aristocracy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('peasant-1', 'peasant', 'The average peasant worked long hours and owned very little land.', '普通农民工作时间很长,拥有的土地却很少。', 'peasant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slavery-1', 'slavery', 'Slavery was finally abolished in the British Empire in the 1830s.', '19 世纪 30 年代,大英帝国终于废除了奴隶制。', 'Slavery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tribe-1', 'tribe', 'Each tribe in the region had its own customs and leaders.', '该地区的每个部落都有自己的习俗和首领。', 'tribe');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('indigenous-1', 'indigenous', 'Indigenous peoples have lived on this land for thousands of years.', '本土民族在这片土地上生活了数千年。', 'Indigenous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aboriginal-1', 'aboriginal', 'Aboriginal Australians have one of the oldest continuous cultures in the world.', '澳大利亚土著拥有世界上最古老的延续文化之一。', 'Aboriginal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('settlement-1', 'settlement', 'The first settlement in the valley was founded around 4000 BC.', '山谷中最早的定居点约建于公元前 4000 年。', 'settlement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('settlement-2', 'settlement', 'The two countries reached a peaceful settlement of the border dispute.', '两国和平解决了边界争端。', 'settlement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('settler-1', 'settler', 'European settlers brought new crops and diseases to the continent.', '欧洲定居者把新作物和疾病带到了这片大陆。', 'settlers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('colonise-1', 'colonise', 'European powers began to colonise large parts of Africa in the 1880s.', '19 世纪 80 年代,欧洲列强开始殖民非洲的大片地区。', 'colonise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('conquest-1', 'conquest', 'The Norman conquest of 1066 brought thousands of French words into English.', '1066 年的诺曼征服把成千上万的法语词带入了英语。', 'conquest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invade-1', 'invade', 'The Vikings began to invade the coast of Britain in the eighth century.', '维京人从八世纪起开始入侵不列颠海岸。', 'invade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revolution-1', 'revolution', 'The French Revolution changed the political map of Europe.', '法国大革命改变了欧洲的政治版图。', 'Revolution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('industrial-revolution-1', 'industrial-revolution', 'The Industrial Revolution brought millions of people from the country to the cities.', '工业革命使数百万人从乡村来到城市。', 'Industrial Revolution');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('renaissance-1', 'renaissance', 'The Renaissance began in Italy and spread across much of Europe.', '文艺复兴始于意大利,并传播到欧洲大部分地区。', 'Renaissance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heritage-1', 'heritage', 'The old town is an important part of the country''s cultural heritage.', '这座老城是该国文化遗产的重要组成部分。', 'heritage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legacy-1', 'legacy', 'The roads built by the Romans are a lasting legacy of their empire.', '罗马人修建的道路是其帝国留下的长久遗产。', 'legacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chronicle-1', 'chronicle', 'A monk wrote a detailed chronicle of events during the king''s reign.', '一位修道士详细记录了国王统治时期的事件,写成编年史。', 'chronicle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chronological-1', 'chronological', 'The objects are displayed in chronological order, from oldest to newest.', '这些物品按时间顺序展出,从最古老的到最新的。', 'chronological');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('era-1', 'era', 'The arrival of the railway marked the beginning of a new era.', '铁路的到来标志着一个新时代的开始。', 'era');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('epoch-1', 'epoch', 'The fossils date from an epoch when the climate was much warmer.', '这些化石来自气候温暖得多的一个纪元。', 'epoch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('descend-1', 'descend', 'Modern English is thought to descend from a language spoken in northern Germany.', '人们认为现代英语传自德国北部使用的一种语言。', 'descend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('origin-1', 'origin', 'The origin of the custom is still a matter of debate among historians.', '这个习俗的起源至今仍是历史学家争论的问题。', 'origin');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('myth-1', 'myth', 'The myth tells how the first people came to live on the island.', '这个神话讲述了最早的人类如何来到岛上生活。', 'myth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('legend-1', 'legend', 'According to legend, the city was founded by two brothers.', '据传说,这座城市是由两兄弟建立的。', 'legend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ritual-1', 'ritual', 'The ritual is performed each spring to ensure a good harvest.', '每年春天都举行这种仪式,以祈求丰收。', 'ritual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ceremony-1', 'ceremony', 'The new king was crowned in a long ceremony at the cathedral.', '新国王在大教堂举行的漫长典礼上加冕。', 'ceremony');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('worship-1', 'worship', 'Ancient people often worshipped the sun as the source of life.', '古人常常把太阳当作生命之源来崇拜。', 'worshipped');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sacred-1', 'sacred', 'The mountain is sacred to the people who live around it.', '这座山对周围的居民来说是神圣的。', 'sacred');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nomad-1', 'nomad', 'Each nomad family moved its animals to new grass with the seasons.', '每个游牧家庭都随季节把牲畜迁到新的草场。', 'nomad');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nomadic-1', 'nomadic', 'Nomadic people often travelled long distances in search of food for their animals.', '游牧民族常常长途跋涉,为牲畜寻找食物。', 'Nomadic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hunter-gatherer-1', 'hunter-gatherer', 'A hunter-gatherer society depends on wild animals and plants for food.', '狩猎采集社会依靠野生动植物获取食物。', 'hunter-gatherer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unearth-1', 'unearth', 'Farmers often unearth Roman coins while ploughing their fields.', '农民在犁田时经常挖出罗马硬币。', 'unearth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petrify-1', 'petrify', 'Over millions of years, minerals can petrify the wood of fallen trees.', '数百万年间,矿物质能使倒下的树木石化。', 'petrify');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skull-1', 'skull', 'The shape of the skull suggests that this person lived on a hard diet.', '头骨的形状表明此人的饮食较硬。', 'skull');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hominid-1', 'hominid', 'The bones belong to an early hominid that lived about three million years ago.', '这些骨头属于约三百万年前的一种早期原始人类。', 'hominid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('primitive-1', 'primitive', 'The first boats were primitive structures made from hollow logs.', '最早的船是用空心原木做成的简陋结构。', 'primitive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('archaic-1', 'archaic', 'The legal document was written in an archaic form of the language.', '这份法律文件是用这种语言的古老形式写成的。', 'archaic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('remnant-1', 'remnant', 'The small forest is a remnant of the woodland that once covered the country.', '这片小森林是曾经覆盖全国的林地的残余。', 'remnant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('antiquity-1', 'antiquity', 'The city has been an important centre of trade since antiquity.', '这座城市自古代起就是重要的贸易中心。', 'antiquity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('neolithic-1', 'neolithic', 'Neolithic farmers cleared the forests and began to grow crops here.', '新石器时代的农民在这里清除森林,开始种植庄稼。', 'Neolithic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('paleolithic-1', 'paleolithic', 'Paleolithic people lived in small groups and made tools from stone.', '旧石器时代的人小群体生活,用石头制作工具。', 'Paleolithic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anthropologist-1', 'anthropologist', 'The anthropologist lived with the tribe for two years to study their customs.', '这位人类学家与部落一起生活了两年,研究他们的习俗。', 'anthropologist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('posterity-1', 'posterity', 'These recordings were made to preserve the language for posterity.', '这些录音是为了给后代保存这种语言。', 'posterity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('forefather-1', 'forefather', 'Local people still use the farming methods of their forefathers.', '当地人仍在使用祖先的耕作方法。', 'forefathers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clan-1', 'clan', 'Each clan in the Scottish Highlands had its own leader and land.', '苏格兰高地的每个宗族都有自己的首领和土地。', 'clan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patriarchal-1', 'patriarchal', 'In patriarchal societies, property usually passes from father to son.', '在父权制社会中,财产通常由父亲传给儿子。', 'patriarchal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enslave-1', 'enslave', 'Invaders would often enslave the people of the towns they captured.', '入侵者常常奴役被他们占领的城镇的居民。', 'enslave');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('abdicate-1', 'abdicate', 'The king was forced to abdicate after he lost the support of the army.', '失去军队支持后,国王被迫退位。', 'abdicate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('palace-1', 'palace', 'The palace was built with marble brought from far across the empire.', '这座宫殿用从帝国遥远地区运来的大理石建造。', 'palace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('temple-1', 'temple', 'The temple stands on a hill and can be seen from miles away.', '寺庙矗立在山上,几英里外都能看到。', 'temple');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cathedral-1', 'cathedral', 'It took nearly two hundred years to complete the great cathedral.', '这座宏伟的大教堂花了近两百年才建成。', 'cathedral');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spire-1', 'spire', 'The cathedral''s tall spire can be seen from anywhere in the city.', '从城里任何地方都能看到大教堂高耸的尖塔。', 'spire');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fort-1', 'fort', 'The Romans built a fort here to protect the crossing of the river.', '罗马人在这里修建了一座堡垒,以保护渡河口。', 'fort');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('siege-1', 'siege', 'The city survived a siege lasting more than two years.', '这座城市在长达两年多的围攻中幸存了下来。', 'siege');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expedition-1', 'expedition', 'The expedition to the South Pole was hit by terrible weather.', '前往南极的探险遭遇了恶劣的天气。', 'expedition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('armour-1', 'armour', 'Metal armour protected knights in battle but made movement difficult.', '金属盔甲在战斗中保护骑士,但也使行动不便。', 'armour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('religion-1', 'religion', 'Religion played a central part in the daily life of medieval people.', '宗教在中世纪人们的日常生活中占据核心地位。', 'Religion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('buddhism-1', 'buddhism', 'Buddhism spread from India to China along the old trade routes.', '佛教沿着古老的贸易路线从印度传到中国。', 'Buddhism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('taoism-1', 'taoism', 'Taoism teaches that people should live in harmony with the natural world.', '道教主张人应与自然和谐相处。', 'Taoism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('christianity-1', 'christianity', 'Christianity spread rapidly through the Roman Empire after the fourth century.', '四世纪后,基督教在罗马帝国迅速传播。', 'Christianity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('atheism-1', 'atheism', 'The book traces the growth of atheism in nineteenth-century Europe.', '这本书追溯了十九世纪欧洲无神论的发展。', 'atheism');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('creed-1', 'creed', 'People of every race and creed were welcome in the port city.', '这座港口城市欢迎各个种族和信条的人。', 'creed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('doctrine-1', 'doctrine', 'The church''s doctrine had a strong influence on medieval science.', '教会的教义对中世纪科学产生了强烈影响。', 'doctrine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dogma-1', 'dogma', 'Scientists should be careful not to treat a popular theory as dogma.', '科学家应小心不要把流行的理论当成教条。', 'dogma');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heresy-1', 'heresy', 'In the past, people could be punished severely for heresy.', '过去,人们可能因异端而受到严厉惩罚。', 'heresy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cult-1', 'cult', 'The sun was the centre of an important religious cult in ancient Egypt.', '太阳是古埃及一种重要宗教崇拜的中心。', 'cult');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('devout-1', 'devout', 'The king was a devout man who built many churches during his reign.', '这位国王很虔诚,在位期间建造了许多教堂。', 'devout');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('preach-1', 'preach', 'Travelling monks would preach to people in towns along the road.', '云游的修道士会向沿途城镇的人布道。', 'preach');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prophet-1', 'prophet', 'The prophet is said to have warned the people about the coming flood.', '据说这位先知曾警告人们洪水即将来临。', 'prophet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('destiny-1', 'destiny', 'Many ancient people believed that the stars controlled human destiny.', '许多古人相信星辰掌控着人类的命运。', 'destiny');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('taboo-1', 'taboo', 'In some cultures, there is a strict taboo against eating certain animals.', '在一些文化中,吃某些动物有严格的禁忌。', 'taboo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rite-1', 'rite', 'The rite marks the moment when a young person becomes an adult.', '这一仪式标志着年轻人成年的时刻。', 'rite');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ghost-1', 'ghost', 'Many old stories tell of the ghost of a king who haunts the castle.', '许多古老的故事讲述一位国王的鬼魂在城堡中出没。', 'ghost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invasion-1', 'invasion', 'The invasion of 1066 changed the course of English history.', '1066 年的入侵改变了英国历史的进程。', 'invasion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sword-1', 'sword', 'Only wealthy warriors could afford a sword made from good steel.', '只有富有的武士才买得起优质钢制成的剑。', 'sword');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('reconstruct-1', 'reconstruct', 'Scientists used the bones to reconstruct the appearance of the animal.', '科学家用这些骨头重构了这种动物的外貌。', 'reconstruct');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('scroll-1', 'scroll', 'Ancient texts were often written on a long scroll of paper.', '古代文本常常写在长长的纸质卷轴上。', 'scroll');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('circa-1', 'circa', 'The palace was built circa 1500 BC, according to the archaeologists.', '据考古学家说,这座宫殿约建于公元前 1500 年。', 'circa');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crown-1', 'crown', 'The crown passed to the king''s younger brother after his death.', '国王死后,王权传给了他的弟弟。', 'crown');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('imperial-1', 'imperial', 'The imperial court employed thousands of officials and servants.', '皇室朝廷雇用了数千名官员和仆人。', 'imperial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chapel-1', 'chapel', 'The small chapel on the island was built by monks in the seventh century.', '岛上这座小教堂是七世纪时修道士建造的。', 'chapel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('spiritual-1', 'spiritual', 'Mountains had a deep spiritual meaning for many ancient cultures.', '高山对许多古代文化有着深刻的精神意义。', 'spiritual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('miracle-1', 'miracle', 'Local people considered the survival of the whole crew a miracle.', '当地人认为全体船员幸存下来是个奇迹。', 'miracle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('divine-1', 'divine', 'Kings once claimed that their power had a divine origin.', '国王们曾声称他们的权力来自神。', 'divine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('triumph-1', 'triumph', 'The opening of the canal was a triumph of nineteenth-century engineering.', '运河的开通是十九世纪工程学的一次胜利。', 'triumph');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('combat-1', 'combat', 'Knights trained from childhood to prepare for combat on horseback.', '骑士从小接受训练,为骑马作战做准备。', 'combat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('combat-2', 'combat', 'New laws were passed to combat corruption in the government.', '新法律的出台是为了打击政府腐败。', 'combat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defeat-1', 'defeat', 'The defeat of the army led to the end of the empire.', '军队的失败导致了帝国的终结。', 'defeat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('defeat-2', 'defeat', 'The small kingdom managed to defeat a much larger invading force.', '这个小王国成功击败了规模大得多的入侵军队。', 'defeat');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fleet-1', 'fleet', 'A great fleet of ships carried soldiers across the Mediterranean.', '一支庞大的舰队载着士兵穿越地中海。', 'fleet');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artillery-1', 'artillery', 'Heavy artillery could destroy the old stone walls of a castle.', '重型火炮能摧毁城堡古老的石墙。', 'artillery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ammunition-1', 'ammunition', 'The army ran out of ammunition after a month of fighting.', '经过一个月的战斗,军队的弹药用完了。', 'ammunition');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shield-1', 'shield', 'Each soldier carried a round shield made of wood and leather.', '每个士兵都拿着一面用木头和皮革制成的圆盾。', 'shield');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shield-2', 'shield', 'Thick walls were designed to shield the town from attack.', '厚厚的城墙是为了保护小镇免受攻击。', 'shield');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('exile-1', 'exile', 'The former leader lived in exile for the rest of his life.', '这位前领导人的余生都在流亡中度过。', 'exile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nobility-1', 'nobility', 'Members of the nobility paid almost no taxes before the revolution.', '革命前,贵族成员几乎不用缴税。', 'nobility');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('millennium-1', 'millennium', 'The town has been a centre of trade for more than a millennium.', '一千多年来,这座城镇一直是贸易中心。', 'millennium');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revolt-1', 'revolt', 'Peasants rose in revolt against the high taxes demanded by the king.', '农民起义反抗国王征收的重税。', 'revolt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('massacre-1', 'massacre', 'The massacre of the villagers caused anger across the whole country.', '对村民的大屠杀引起了全国的愤怒。', 'massacre');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('assassination-1', 'assassination', 'The assassination of the archduke in 1914 helped to start the First World War.', '1914 年大公遇刺促成了第一次世界大战的爆发。', 'assassination');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('curse-1', 'curse', 'According to popular stories, a curse protected the tomb from thieves.', '根据民间传说,诅咒保护着这座陵墓免遭盗窃。', 'curse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cannon-1', 'cannon', 'The new cannon could fire heavy stone balls over great distances.', '这种新式大炮能把沉重的石弹射得很远。', 'cannon');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('burial-1', 'burial', 'Gold and weapons were placed in the burial chamber of the king.', '黄金和武器被放在国王的墓室里。', 'burial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cemetery-1', 'cemetery', 'The old cemetery contains the graves of many early settlers.', '这座老墓地里有许多早期定居者的坟墓。', 'cemetery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mosaic-1', 'mosaic', 'A beautiful Roman mosaic was discovered beneath the floor of the old church.', '在老教堂的地板下发现了一幅精美的罗马马赛克镶嵌画。', 'mosaic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('architecture-1', 'architecture', 'The city''s architecture reflects the influence of several different cultures.', '这座城市的建筑风格反映了几种不同文化的影响。', 'architecture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('architect-1', 'architect', 'The architect designed the museum to make the best use of natural light.', '建筑师在设计博物馆时充分利用了自然光。', 'architect');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('architectural-1', 'architectural', 'The old railway station is one of the town''s finest architectural treasures.', '这座老火车站是镇上最精美的建筑瑰宝之一。', 'architectural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('structure-1', 'structure', 'The structure of the building allows it to move during an earthquake.', '这座建筑的结构使它能在地震时摆动。', 'structure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foundation-1', 'foundation', 'Soft ground meant that the foundation of the tower had to be very deep.', '地面松软,所以塔的地基必须打得很深。', 'foundation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('foundation-2', 'foundation', 'A charitable foundation paid for the restoration of the old library.', '一家慈善基金会出资修复了这座旧图书馆。', 'foundation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pillar-1', 'pillar', 'Huge stone pillars support the roof of the ancient temple.', '巨大的石柱支撑着古庙的屋顶。', 'pillars');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('column-1', 'column', 'The front of the building is decorated with tall marble columns.', '建筑正面装饰着高大的大理石圆柱。', 'columns');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('column-2', 'column', 'Her weekly newspaper column discusses issues in modern education.', '她每周的报纸专栏讨论现代教育问题。', 'column');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('beam-1', 'beam', 'Heavy wooden beams hold up the roof of the old market hall.', '沉重的木横梁支撑着老市场大厅的屋顶。', 'beams');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('arch-1', 'arch', 'The Romans used the arch to build long bridges and large buildings.', '罗马人利用拱修建长桥和大型建筑。', 'arch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dome-1', 'dome', 'The great dome of the cathedral took more than sixteen years to build.', '大教堂的巨大穹顶花了十六年多才建成。', 'dome');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('facade-1', 'facade', 'The historic facade was kept when the rest of the building was replaced.', '建筑其余部分被更换时,这面历史悠久的建筑正面保留了下来。', 'facade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skyscraper-1', 'skyscraper', 'The development of the steel frame made the first skyscraper possible.', '钢框架的发展使第一座摩天大楼成为可能。', 'skyscraper');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('high-rise-1', 'high-rise', 'High-rise flats were built quickly to replace homes destroyed in the war.', '人们迅速建起高层公寓,以取代在战争中被毁的房屋。', 'High-rise');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('storey-1', 'storey', 'The new office building will be twenty storeys high.', '新办公楼将有二十层高。', 'storeys');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concrete-1', 'concrete', 'Concrete is now the most widely used building material in the world.', '混凝土现在是世界上使用最广泛的建筑材料。', 'Concrete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('concrete-2', 'concrete', 'The study offers few concrete suggestions for solving the problem.', '这项研究几乎没有提出解决问题的具体建议。', 'concrete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('steel-1', 'steel', 'The use of steel allowed engineers to build much longer bridges.', '钢材的使用使工程师能够建造更长的桥梁。', 'steel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('material-1', 'material', 'Bamboo is a popular building material in many parts of Asia.', '竹子在亚洲许多地区都是很受欢迎的建筑材料。', 'material');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('blueprint-1', 'blueprint', 'The engineer''s original blueprint for the bridge is kept in the city museum.', '工程师最初的桥梁蓝图保存在市博物馆。', 'blueprint');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('engineer-1', 'engineer', 'The engineer who designed the tunnel was just twenty-six years old.', '设计这条隧道的工程师年仅二十六岁。', 'engineer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('infrastructure-1', 'infrastructure', 'Poor infrastructure is holding back economic growth in rural areas.', '基础设施落后阻碍了农村地区的经济增长。', 'infrastructure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('urban-1', 'urban', 'More than half of the world''s population now lives in urban areas.', '世界上一半以上的人口现在居住在城市地区。', 'urban');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rural-1', 'rural', 'Young people are leaving rural areas to look for work in the cities.', '年轻人正在离开农村地区,去城市找工作。', 'rural');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suburban-1', 'suburban', 'Suburban families tend to rely on private cars for almost every journey.', '郊区家庭几乎每次出行都依赖私家车。', 'Suburban');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('metropolis-1', 'metropolis', 'The small port grew into a huge metropolis within a hundred years.', '这个小港口在一百年内发展成了一座大都市。', 'metropolis');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('urbanisation-1', 'urbanisation', 'Rapid urbanisation has put heavy pressure on housing and water supplies.', '快速城市化给住房和供水带来了沉重压力。', 'urbanisation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('urban-sprawl-1', 'urban-sprawl', 'Urban sprawl has replaced large areas of farmland with low-density housing.', '城市扩张使大片农田变成了低密度住宅区。', 'Urban sprawl');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('population-density-1', 'population-density', 'Tokyo has a very high population density compared with most other cities.', '与大多数其他城市相比,东京的人口密度非常高。', 'population density');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('congestion-1', 'congestion', 'A charge for driving in the city centre has reduced traffic congestion.', '市中心行车收费减少了交通拥堵。', 'congestion');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slum-1', 'slum', 'Millions of people in the region live in a slum without clean water.', '该地区有数百万人住在没有清洁用水的贫民窟。', 'slum');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('housing-1', 'housing', 'The shortage of cheap housing is a serious problem for young workers.', '廉价住房短缺对年轻工人来说是个严重问题。', 'housing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('residential-1', 'residential', 'The new road will run through a quiet residential part of the city.', '新路将穿过城市一处安静的住宅区。', 'residential');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commercial-1', 'commercial', 'The old warehouses have been turned into commercial and office space.', '这些旧仓库被改造成了商业和办公空间。', 'commercial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('industrial-1', 'industrial', 'Many industrial cities declined when the factories closed down.', '工厂关闭后,许多工业城市衰落了。', 'industrial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('zone-1', 'zone', 'Cars are not allowed in the pedestrian zone at the centre of town.', '市中心的步行区不允许汽车通行。', 'zone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('district-1', 'district', 'The old financial district is now full of shops and restaurants.', '老金融区现在到处是商店和餐馆。', 'district');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('municipal-1', 'municipal', 'Municipal authorities are responsible for collecting rubbish and repairing local roads.', '市政当局负责收集垃圾和维修当地道路。', 'Municipal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('council-1', 'council', 'The city council voted to create more bicycle lanes in the centre.', '市议会投票决定在市中心增设更多自行车道。', 'council');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('planning-permission-1', 'planning-permission', 'The company needs planning permission before it can build on the land.', '公司要在这块土地上建房,必须先获得规划许可。', 'planning permission');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('green-belt-1', 'green-belt', 'Building is strictly limited on the green belt around the city.', '城市周围的绿化带严格限制建房。', 'green belt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-space-1', 'public-space', 'Good public space encourages people to spend more time outdoors.', '良好的公共空间鼓励人们更多地待在户外。', 'public space');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('heritage-building-1', 'heritage-building', 'Developers are not allowed to change the outside of a heritage building.', '开发商不得改变历史建筑的外观。', 'heritage building');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('restoration-1', 'restoration', 'The restoration of the old theatre cost more than ten million pounds.', '这座老剧院的修复花费超过一千万英镑。', 'restoration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sewage-1', 'sewage', 'Untreated sewage can pollute drinking water and spread serious diseases.', '未经处理的污水会污染饮用水,传播严重疾病。', 'sewage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('drainage-1', 'drainage', 'Poor drainage caused the streets to flood after heavy rain.', '排水系统不畅导致街道在大雨后被淹。', 'drainage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ventilation-1', 'ventilation', 'Good ventilation is essential in buildings with a large number of people.', '在人员众多的建筑里,良好的通风至关重要。', 'ventilation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('eaves-1', 'eaves', 'Birds often build their nests under the eaves of old houses.', '鸟常常在老房子的屋檐下筑巢。', 'eaves');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('thatch-1', 'thatch', 'Cottages with a roof of thatch are common in this part of England.', '茅草屋顶的小屋在英格兰这一地区很常见。', 'thatch');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('clay-1', 'clay', 'Bricks are made by baking clay at very high temperatures.', '砖是把黏土在高温下烧制而成的。', 'clay');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('asphalt-1', 'asphalt', 'Dark asphalt roads absorb heat and make cities warmer in summer.', '深色的沥青路面吸收热量,使城市夏天更热。', 'asphalt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shelter-1', 'shelter', 'The caves provided shelter for early people during the coldest months.', '这些洞穴在最冷的几个月为早期人类提供了庇护。', 'shelter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shelter-2', 'shelter', 'Trees planted along the coast shelter the town from strong winds.', '沿海种植的树木为小镇挡住了强风。', 'shelter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cityscape-1', 'cityscape', 'Tall glass buildings have transformed the cityscape over the past twenty years.', '过去二十年,高大的玻璃建筑改变了城市景观。', 'cityscape');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('metropolitan-1', 'metropolitan', 'The metropolitan area now has a population of nearly ten million.', '这一大都市地区现在的人口接近一千万。', 'metropolitan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('municipality-1', 'municipality', 'Each municipality is responsible for running its own schools.', '每个自治市负责管理自己的学校。', 'municipality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('county-1', 'county', 'The county is known for its farming and its old market towns.', '这个郡以农业和古老的集镇闻名。', 'county');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('provincial-1', 'provincial', 'Provincial governments have been given more control over health spending.', '省级政府获得了对医疗支出更大的控制权。', 'Provincial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rustic-1', 'rustic', 'The hotel has a rustic charm, with stone walls and wooden furniture.', '这家酒店有一种乡村韵味,石墙配木制家具。', 'rustic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inhabitant-1', 'inhabitant', 'The island''s first inhabitants arrived by boat about three thousand years ago.', '这座岛最早的居民大约三千年前乘船来到这里。', 'inhabitants');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('resident-1', 'resident', 'Local residents have complained about noise from the new airport.', '当地居民投诉新机场的噪音。', 'residents');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('demography-1', 'demography', 'Changes in demography will affect the demand for schools and hospitals.', '人口结构的变化将影响对学校和医院的需求。', 'demography');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bottleneck-1', 'bottleneck', 'The narrow bridge has become a serious bottleneck for traffic entering the city.', '这座窄桥已成为进城交通的严重瓶颈。', 'bottleneck');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('residential-area-1', 'residential-area', 'The new train line will connect the main residential area with the city centre.', '新铁路线将把主要住宅区与市中心连接起来。', 'residential area');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('central-business-district-1', 'central-business-district', 'Office rents are highest in the central business district of the city.', '城市中央商务区的办公室租金最高。', 'central business district');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('real-estate-1', 'real-estate', 'Foreign investors have been buying real estate in the capital.', '外国投资者一直在首都购买房地产。', 'real estate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('block-of-flats-1', 'block-of-flats', 'The block of flats was built in the 1960s to house factory workers.', '这栋公寓楼建于 20 世纪 60 年代,供工厂工人居住。', 'block of flats');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('planner-1', 'planner', 'Every planner must think about the long-term effects of new roads.', '每位规划者都必须考虑新道路的长期影响。', 'planner');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slab-1', 'slab', 'A huge stone slab covered the entrance to the ancient tomb.', '一块巨大的石板盖住了古墓的入口。', 'slab');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('partition-1', 'partition', 'Thin partitions divide the large office into smaller working areas.', '薄隔断把大办公室分成了较小的工作区。', 'partitions');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interior-1', 'interior', 'The interior of the building has been completely modernised.', '建筑内部已经完全现代化了。', 'interior');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chamber-1', 'chamber', 'The king''s burial chamber was discovered beneath the floor of the hall.', '国王的墓室是在大厅地板下发现的。', 'chamber');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('erect-1', 'erect', 'Workers erected the entire tower in less than two years.', '工人们用不到两年时间建成了整座塔。', 'erected');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enclosure-1', 'enclosure', 'The animals are kept in a large enclosure at the edge of the park.', '这些动物被养在公园边缘的一个大围场里。', 'enclosure');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shaft-1', 'shaft', 'Miners went down a deep shaft to reach the coal below.', '矿工们下到深深的竖井中采煤。', 'shaft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('locality-1', 'locality', 'Each locality has its own traditions and style of cooking.', '每个地区都有自己的传统和烹饪风格。', 'locality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('perimeter-1', 'perimeter', 'A high wall runs around the entire perimeter of the old city.', '一道高墙环绕着老城的整个周边。', 'perimeter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('vehicle-1', 'vehicle', 'Every vehicle entering the city centre must now pay a daily charge.', '现在每辆进入市中心的车辆都要付每日费用。', 'vehicle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('automobile-1', 'automobile', 'The invention of the automobile changed the shape of modern cities.', '汽车的发明改变了现代城市的形态。', 'automobile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('engine-1', 'engine', 'The steam engine made it possible to power factories without water.', '蒸汽机使工厂不用水力也能运转。', 'engine');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('motor-1', 'motor', 'The small electric motor turns the wheels at a constant speed.', '这台小型电动马达以恒定的速度驱动车轮。', 'motor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fuel-1', 'fuel', 'Ships use huge quantities of fuel on their long voyages.', '船舶在远航中消耗大量燃料。', 'fuel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('petrol-1', 'petrol', 'The price of petrol has a direct effect on the cost of transport.', '汽油价格直接影响运输成本。', 'petrol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('diesel-1', 'diesel', 'Many cities plan to ban diesel cars in order to improve air quality.', '许多城市计划禁止柴油车,以改善空气质量。', 'diesel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electric-vehicle-1', 'electric-vehicle', 'An electric vehicle produces no exhaust fumes while it is being driven.', '电动汽车行驶时不产生尾气。', 'electric vehicle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hybrid-1', 'hybrid', 'A hybrid uses both a petrol engine and an electric motor.', '混合动力汽车同时使用汽油发动机和电动马达。', 'hybrid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('railway-1', 'railway', 'The railway brought rapid economic growth to the towns along its route.', '铁路给沿线城镇带来了快速的经济增长。', 'railway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('locomotive-1', 'locomotive', 'The first steam locomotive could pull only a few small wagons.', '第一台蒸汽机车只能拉几节小车厢。', 'locomotive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('high-speed-rail-1', 'high-speed-rail', 'High-speed rail has greatly reduced journey times between the major cities.', '高铁大大缩短了主要城市之间的行程时间。', 'High-speed rail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aviation-1', 'aviation', 'Early aviation was very dangerous, and many pilots lost their lives.', '早期航空非常危险,许多飞行员丧生。', 'aviation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('aircraft-1', 'aircraft', 'New aircraft use far less fuel than those built thirty years ago.', '新飞机比三十年前制造的飞机省油得多。', 'aircraft');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('runway-1', 'runway', 'A second runway would allow the airport to handle many more flights.', '第二条跑道将使机场能够处理更多航班。', 'runway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('navigation-1', 'navigation', 'Satellites have made navigation far easier for ships and aircraft.', '卫星使船舶和飞机的导航容易多了。', 'navigation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('canal-1', 'canal', 'Goods were carried along the canal from the coast to the factories.', '货物沿运河从海岸运到工厂。', 'canal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tunnel-1', 'tunnel', 'The new tunnel under the river will take five years to complete.', '河底的新隧道需要五年才能建成。', 'tunnel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dam-1', 'dam', 'The dam provides electricity for millions of people but has damaged river life.', '这座水坝为数百万人供电,却破坏了河流生态。', 'dam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('highway-1', 'highway', 'A new highway has reduced the journey between the two cities by an hour.', '一条新公路使两座城市之间的路程缩短了一小时。', 'highway');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('freight-1', 'freight', 'More freight is now carried by road than by rail in most countries.', '在大多数国家,现在公路货运量超过铁路。', 'freight');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cargo-1', 'cargo', 'The ship was carrying a cargo of grain when it sank.', '这艘船沉没时正运载着一批谷物。', 'cargo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('logistics-1', 'logistics', 'Online shopping has created new challenges for logistics companies.', '网购给物流公司带来了新的挑战。', 'logistics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('public-transport-1', 'public-transport', 'Cheap public transport can reduce the number of cars on the road.', '便宜的公共交通可以减少路上的汽车数量。', 'public transport');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commuter-1', 'commuter', 'The average commuter spends more than an hour a day travelling to work.', '普通通勤者每天上班路上要花一个多小时。', 'commuter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('traffic-jam-1', 'traffic-jam', 'Each traffic jam costs the economy a great deal in lost working time.', '每次交通堵塞都因工作时间损失给经济带来巨大代价。', 'traffic jam');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('rush-hour-1', 'rush-hour', 'Buses are often overcrowded during the morning rush hour.', '早高峰期间,公交车经常超载。', 'rush hour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collision-1', 'collision', 'A collision between two ships closed the port for several days.', '两艘船相撞导致港口关闭数日。', 'collision');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('speed-limit-1', 'speed-limit', 'Lowering the speed limit has reduced serious accidents near schools.', '降低限速减少了学校附近的严重事故。', 'speed limit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('driverless-car-1', 'driverless-car', 'A driverless car uses sensors and cameras to follow the road.', '无人驾驶汽车利用传感器和摄像头沿道路行驶。', 'driverless car');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mechanical-1', 'mechanical', 'Mechanical clocks were first built in European churches in the Middle Ages.', '机械钟最早是中世纪在欧洲教堂建造的。', 'Mechanical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('device-1', 'device', 'The small device measures the level of oxygen in the blood.', '这个小装置测量血液中的氧含量。', 'device');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('apparatus-1', 'apparatus', 'The scientist built a simple apparatus to test his idea about air.', '这位科学家制作了一个简单的器械来检验他关于空气的想法。', 'apparatus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gear-1', 'gear', 'A bicycle''s gears make it easier to ride up steep hills.', '自行车的齿轮使骑车上陡坡更容易。', 'gears');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('axle-1', 'axle', 'The wheels turn on a metal axle fixed underneath the cart.', '车轮绕着固定在车下的金属车轴转动。', 'axle');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lever-1', 'lever', 'A long lever allows a person to lift a very heavy stone.', '长杠杆让人能抬起很重的石头。', 'lever');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('pulley-1', 'pulley', 'With a pulley, workers could raise heavy stones to the top of the wall.', '利用滑轮,工人能把沉重的石头吊到墙顶。', 'pulley');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('propeller-1', 'propeller', 'The ship''s large propeller is driven by a powerful diesel engine.', '这艘船的大螺旋桨由强力柴油发动机驱动。', 'propeller');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prototype-1', 'prototype', 'Engineers tested the prototype for several months before starting production.', '工程师对原型测试了几个月才开始生产。', 'prototype');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patent-1', 'patent', 'The inventor applied for a patent to protect his new design.', '这位发明家申请了专利,以保护他的新设计。', 'patent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('invention-1', 'invention', 'The invention of the telephone transformed the way people communicate.', '电话的发明彻底改变了人们的交流方式。', 'invention');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inventor-1', 'inventor', 'The inventor of the machine died before he could see its success.', '这台机器的发明者没能看到它的成功就去世了。', 'inventor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('accelerate-1', 'accelerate', 'Rising temperatures may accelerate the melting of the polar ice.', '气温上升可能加速极地冰层的融化。', 'accelerate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('decelerate-1', 'decelerate', 'Economic growth began to decelerate towards the end of the decade.', '到这十年的末期,经济增长开始放缓。', 'decelerate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brake-1', 'brake', 'The driver''s foot pressed the brake just before the collision.', '就在相撞之前,司机踩下了刹车。', 'brake');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('skid-1', 'skid', 'Cars may skid on wet roads if their tyres are worn.', '如果轮胎磨损,汽车在湿滑路面上可能打滑。', 'skid');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('traction-1', 'traction', 'Wide tyres give the vehicle better traction on soft sand.', '宽轮胎让车辆在软沙上有更好的牵引力。', 'traction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspension-1', 'suspension', 'A good suspension system makes the ride more comfortable on rough roads.', '良好的悬架系统使车辆在崎岖路面上行驶更舒适。', 'suspension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('suspension-2', 'suspension', 'The suspension of the train service caused long delays for commuters.', '火车停运给通勤者造成了长时间延误。', 'suspension');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('windscreen-1', 'windscreen', 'Laminated glass prevents the windscreen from breaking into sharp pieces.', '夹层玻璃防止挡风玻璃碎成锋利的碎片。', 'windscreen');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('guardrail-1', 'guardrail', 'The car hit the guardrail but did not fall from the bridge.', '汽车撞上了护栏,但没有从桥上掉下去。', 'guardrail');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('helicopter-1', 'helicopter', 'A helicopter was used to rescue people from the flooded village.', '人们用直升机营救被洪水围困的村民。', 'helicopter');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cyclist-1', 'cyclist', 'Each cyclist in the city benefits from the new network of separate lanes.', '城里的每位骑车人都受益于新的独立车道网络。', 'cyclist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('machinery-1', 'machinery', 'New farm machinery reduced the number of workers needed on the land.', '新的农业机器减少了田间所需的工人数量。', 'machinery');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carrier-1', 'carrier', 'Low-cost carriers have made air travel affordable for many more people.', '低成本运输公司让更多人负担得起航空旅行。', 'carriers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('carrier-2', 'carrier', 'A person can be a carrier of the disease without showing any symptoms.', '一个人可能是这种疾病的携带者而没有任何症状。', 'carrier');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('container-1', 'container', 'The use of the shipping container greatly reduced the cost of transporting goods.', '集装箱的使用大大降低了货物运输成本。', 'container');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('radar-1', 'radar', 'Radar was developed to detect enemy aircraft during the war.', '雷达是在战争期间为探测敌机而研制的。', 'Radar');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('valve-1', 'valve', 'The valve controls how much steam enters the engine.', '阀门控制进入发动机的蒸汽量。', 'valve');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cable-1', 'cable', 'A cable under the Atlantic first linked Europe and America by telegraph.', '大西洋海底的电缆首次用电报连接了欧洲和美洲。', 'cable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bolt-1', 'bolt', 'Each steel bolt in the bridge is checked regularly for signs of weakness.', '桥上的每个钢螺栓都定期检查是否有松动迹象。', 'bolt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('anchor-1', 'anchor', 'The ship dropped its anchor in the shelter of the bay.', '船在海湾的避风处抛了锚。', 'anchor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('screw-1', 'screw', 'A tiny loose screw caused the entire machine to stop working.', '一颗松动的小螺丝导致整台机器停止工作。', 'screw');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('coil-1', 'coil', 'An electric current passing through a coil of wire creates a magnetic field.', '电流通过线圈时产生磁场。', 'coil');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crash-1', 'crash', 'The plane crash led to important changes in airline safety rules.', '这次飞机坠毁促使航空安全规则作出重要修改。', 'crash');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('crash-2', 'crash', 'Share prices crashed in 1929, and many investors lost everything.', '1929 年股价暴跌,许多投资者倾家荡产。', 'crashed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('collide-1', 'collide', 'Birds sometimes collide with tall glass buildings during migration.', '鸟类在迁徙时有时会撞上高大的玻璃建筑。', 'collide');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('economy-1', 'economy', 'The local economy depends heavily on fishing and tourism.', '当地经济严重依赖渔业和旅游业。', 'economy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('economic-1', 'economic', 'The country enjoyed a long period of economic growth after the war.', '战后,这个国家经历了长时期的经济增长。', 'economic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('economical-1', 'economical', 'Smaller cars are more economical and produce less pollution.', '小型车更省油,污染也更少。', 'economical');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('economist-1', 'economist', 'One economist argues that higher wages would actually create more jobs.', '一位经济学家认为,提高工资实际上会创造更多就业机会。', 'economist');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('finance-1', 'finance', 'London became a world centre of finance during the nineteenth century.', '十九世纪,伦敦成为世界金融中心。', 'finance');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('financial-1', 'financial', 'Many small businesses are facing serious financial difficulties this year.', '今年许多小企业面临严重的财务困难。', 'financial');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capital-1', 'capital', 'The company needed more capital to develop its new product.', '公司需要更多资本来开发新产品。', 'capital');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('capital-2', 'capital', 'Canberra was chosen as the capital of Australia in 1908.', '1908 年,堪培拉被选为澳大利亚的首都。', 'capital');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('investment-1', 'investment', 'Foreign investment has helped to create jobs in the region.', '外国投资帮助该地区创造了就业机会。', 'investment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('investor-1', 'investor', 'A wise investor spreads risk across several different types of business.', '明智的投资者把风险分散到几种不同类型的企业。', 'investor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('asset-1', 'asset', 'The company''s main asset is its well-known brand name.', '公司的主要资产是它的知名品牌。', 'asset');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('liability-1', 'liability', 'The firm''s liabilities were much greater than the value of its property.', '这家公司的负债远高于其财产的价值。', 'liabilities');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('revenue-1', 'revenue', 'Tourism is an important source of revenue for the national government.', '旅游业是中央政府重要的收入来源。', 'revenue');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('income-1', 'income', 'Average income has risen, but so has the cost of housing.', '平均收入有所上升,但住房成本也上升了。', 'income');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('profit-1', 'profit', 'The company made a large profit from selling its products overseas.', '这家公司在海外销售产品获得了巨额利润。', 'profit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loss-1', 'loss', 'The airline reported a heavy loss for the third year in a row.', '这家航空公司连续第三年报告巨额亏损。', 'loss');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turnover-1', 'turnover', 'The small firm had a turnover of two million pounds last year.', '这家小公司去年的营业额为两百万英镑。', 'turnover');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('turnover-2', 'turnover', 'Low pay has led to a high turnover of staff in the industry.', '低工资导致这个行业的人员流动率很高。', 'turnover');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cost-1', 'cost', 'The cost of solar power has fallen sharply in the last decade.', '过去十年,太阳能的成本急剧下降。', 'cost');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('expense-1', 'expense', 'The expense of maintaining old buildings is a problem for many towns.', '维护老建筑的费用是许多城镇面临的问题。', 'expense');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('inflation-1', 'inflation', 'High inflation reduces the value of people''s savings.', '高通货膨胀会降低人们储蓄的价值。', 'inflation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deflation-1', 'deflation', 'During a period of deflation, consumers often delay buying expensive goods.', '在通货紧缩时期,消费者常常推迟购买昂贵商品。', 'deflation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('recession-1', 'recession', 'Thousands of companies closed during the recession of the early 1990s.', '20 世纪 90 年代初的经济衰退期间,数千家公司倒闭。', 'recession');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('boom-1', 'boom', 'The oil boom brought great wealth to the region in the 1970s.', '20 世纪 70 年代的石油繁荣给该地区带来了巨大财富。', 'boom');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('growth-1', 'growth', 'Economic growth in the region has slowed over the past two years.', '过去两年,该地区的经济增长放缓了。', 'growth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gdp-1', 'gdp', 'Tourism accounts for about ten percent of the country''s GDP.', '旅游业约占该国国内生产总值的百分之十。', 'GDP');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prosperity-1', 'prosperity', 'The new railway brought prosperity to towns along the coast.', '新铁路给沿海城镇带来了繁荣。', 'prosperity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('poverty-1', 'poverty', 'Education is one of the most effective ways of reducing poverty.', '教育是减少贫穷最有效的方法之一。', 'poverty');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wealth-1', 'wealth', 'The town''s wealth came mainly from trade in wool and cloth.', '这个城镇的财富主要来自羊毛和布匹贸易。', 'wealth');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affluent-1', 'affluent', 'People in affluent countries tend to throw away large amounts of food.', '富裕国家的人往往扔掉大量食物。', 'affluent');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tax-1', 'tax', 'A higher tax on fuel could encourage people to drive less.', '提高燃油税可以鼓励人们少开车。', 'tax');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tax-2', 'tax', 'The government decided to tax sugary drinks in order to improve public health.', '政府决定对含糖饮料征税,以改善公众健康。', 'tax');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('taxation-1', 'taxation', 'Progressive taxation means that people with higher incomes pay a larger share.', '累进税收意味着收入较高的人缴纳更大比例的税。', 'taxation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('subsidy-1', 'subsidy', 'A government subsidy keeps the price of bread low in many countries.', '在许多国家,政府补贴使面包价格保持在低水平。', 'subsidy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tariff-1', 'tariff', 'A high tariff on imported steel protected local producers from competition.', '进口钢材的高关税保护了本地生产商免受竞争。', 'tariff');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('trade-1', 'trade', 'Trade between the two regions grew rapidly after the road was built.', '道路修通后,两个地区之间的贸易迅速增长。', 'Trade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('import-1', 'import', 'Imports of cheap clothing have damaged the local textile industry.', '廉价服装的进口损害了当地纺织业。', 'Imports');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('import-2', 'import', 'The country has to import most of its food and energy.', '这个国家的大部分食物和能源都要进口。', 'import');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('export-1', 'export', 'Coffee is still the country''s most important export today.', '咖啡至今仍是该国最重要的出口产品。', 'export');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('export-2', 'export', 'China began to export silk to Europe more than two thousand years ago.', '中国两千多年前就开始向欧洲出口丝绸。', 'export');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('commodity-1', 'commodity', 'Oil is the world''s most heavily traded commodity.', '石油是世界上交易量最大的商品。', 'commodity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('goods-1', 'goods', 'The canal allowed goods to be moved much more cheaply than by road.', '运河使货物运输比公路便宜得多。', 'goods');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('service-1', 'service', 'The banking service has moved almost entirely online in recent years.', '近年来,银行服务几乎完全转到了线上。', 'service');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supply-1', 'supply', 'A reliable water supply is essential for the growth of any city.', '可靠的供水对任何城市的发展都至关重要。', 'supply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('supply-2', 'supply', 'Local farmers supply most of the vegetables sold in the town''s markets.', '当地农民供应镇上市场出售的大部分蔬菜。', 'supply');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('market-1', 'market', 'The market for electric cars has grown rapidly in recent years.', '近年来,电动汽车市场迅速增长。', 'market');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monopoly-1', 'monopoly', 'For many years, the state had a monopoly on the sale of salt.', '多年来,国家垄断了盐的销售。', 'monopoly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('competitor-1', 'competitor', 'The company''s main competitor has just lowered its prices.', '公司的主要竞争者刚刚降低了价格。', 'competitor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('competitive-1', 'competitive', 'Lower wages have helped to make the country''s exports more competitive.', '较低的工资帮助该国的出口产品更具竞争力。', 'competitive');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consumer-1', 'consumer', 'Consumers are increasingly choosing products that do not harm the environment.', '消费者越来越多地选择不损害环境的产品。', 'Consumers');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('consumption-1', 'consumption', 'Meat consumption has risen rapidly as incomes have increased.', '随着收入增加,肉类消费迅速增长。', 'consumption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('producer-1', 'producer', 'The country is the world''s largest producer of coffee.', '这个国家是世界上最大的咖啡生产国。', 'producer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manufacture-1', 'manufacture', 'The factory began to manufacture bicycles at the end of the war.', '这家工厂在战争结束时开始制造自行车。', 'manufacture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('manufacturer-1', 'manufacturer', 'The manufacturer has recalled thousands of cars because of a brake problem.', '由于刹车问题,制造商召回了数千辆汽车。', 'manufacturer');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('industry-1', 'industry', 'The car industry employs thousands of people in the north of the country.', '汽车行业在该国北部雇用了数千人。', 'industry');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sector-1', 'sector', 'The service sector now provides most of the jobs in large cities.', '现在大城市的大部分就业机会来自服务业。', 'sector');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('enterprise-1', 'enterprise', 'State-owned enterprises still control much of the country''s energy supply.', '国有企业仍然控制着该国大部分能源供应。', 'enterprises');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('corporation-1', 'corporation', 'The corporation has offices in more than forty countries.', '这家公司在四十多个国家设有办事处。', 'corporation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('multinational-1', 'multinational', 'Multinational companies can move production to wherever costs are lowest.', '跨国公司可以把生产转移到成本最低的地方。', 'Multinational');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('firm-1', 'firm', 'The firm employs more than two thousand people across Europe.', '这家公司在欧洲各地雇用了两千多人。', 'firm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('firm-2', 'firm', 'The government has taken a firm stand against illegal fishing.', '政府对非法捕鱼采取了坚定的立场。', 'firm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('start-up-1', 'start-up', 'The start-up received funding from investors to develop its new app.', '这家初创公司获得了投资者的资金,用于开发新应用。', 'start-up');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('entrepreneur-1', 'entrepreneur', 'The young entrepreneur built a successful business from a small market stall.', '这位年轻的企业家从一个小摊位起步,建立了成功的企业。', 'entrepreneur');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('shareholder-1', 'shareholder', 'Every shareholder has the right to vote at the annual meeting.', '每位股东都有权在年会上投票。', 'shareholder');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stock-1', 'stock', 'The price of the company''s stock fell sharply after the report.', '报告发表后,该公司的股票价格急剧下跌。', 'stock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stock-2', 'stock', 'Supermarkets now keep very little stock in their own warehouses.', '现在超市自己的仓库里库存很少。', 'stock');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('share-1', 'share', 'The company has been losing its share of the European market.', '这家公司在欧洲市场的份额一直在下降。', 'share');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('share-2', 'share', 'Scientists around the world share their data to speed up research.', '世界各地的科学家分享数据,以加快研究。', 'share');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('dividend-1', 'dividend', 'Shareholders received a higher dividend after a very profitable year.', '在利润丰厚的一年之后,股东们获得了更高的股息。', 'dividend');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bankrupt-1', 'bankrupt', 'Several small airlines went bankrupt when the price of fuel rose.', '燃油价格上涨后,几家小型航空公司破产了。', 'bankrupt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('bankruptcy-1', 'bankruptcy', 'Falling sales forced the company into bankruptcy after fifty years in business.', '销量下滑迫使这家经营了五十年的公司破产。', 'bankruptcy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('debt-1', 'debt', 'Many students leave university with a large amount of debt.', '许多学生大学毕业时背负着大量债务。', 'debt');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interest-1', 'interest', 'Banks charge higher interest on loans to small businesses.', '银行对小企业贷款收取更高的利息。', 'interest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interest-2', 'interest', 'Public interest in the subject has grown in recent years.', '近年来,公众对这个问题的兴趣有所增长。', 'interest');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advertising-1', 'advertising', 'Children are especially easily influenced by television advertising.', '儿童尤其容易受到电视广告的影响。', 'advertising');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advertisement-1', 'advertisement', 'The first newspaper advertisement for the product appeared in 1890.', '这种产品的第一则报纸广告于 1890 年出现。', 'advertisement');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('marketing-1', 'marketing', 'Successful marketing depends on understanding what customers really want.', '成功的市场营销取决于了解顾客真正想要什么。', 'marketing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('brand-1', 'brand', 'People often pay more for a product with a well-known brand.', '人们常常愿意为知名品牌的产品付更多的钱。', 'brand');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('logo-1', 'logo', 'A simple logo helps customers to recognise a company''s products.', '简单的标志有助于顾客识别公司的产品。', 'logo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('slogan-1', 'slogan', 'The company''s slogan was soon known by people across the country.', '这家公司的口号很快就为全国人民所知。', 'slogan');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sales-1', 'sales', 'Sales of printed books have fallen with the growth of digital reading.', '随着数字阅读的发展,纸质书的销售额下降了。', 'Sales');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('client-1', 'client', 'The bank gave each client advice on how to invest their savings.', '银行就如何投资积蓄为每位客户提供建议。', 'client');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merger-1', 'merger', 'The merger of the two banks created one of the largest in Asia.', '两家银行合并后组成了亚洲最大的银行之一。', 'merger');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outsource-1', 'outsource', 'Many companies outsource production to countries where labour is cheaper.', '许多公司把生产外包给劳动力更便宜的国家。', 'outsource');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('productivity-1', 'productivity', 'New technology has greatly increased productivity in the farming sector.', '新技术大大提高了农业部门的生产率。', 'productivity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('efficiency-1', 'efficiency', 'The new engines have improved fuel efficiency by almost a third.', '新发动机把燃油效率提高了近三分之一。', 'efficiency');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('labour-1', 'labour', 'The shortage of cheap labour forced farmers to buy machines.', '廉价劳动力的短缺迫使农民购买机器。', 'labour');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('workforce-1', 'workforce', 'Automation has reduced the size of the workforce in many manufacturing industries.', '自动化缩减了许多制造行业的劳动力规模。', 'workforce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('unemployment-1', 'unemployment', 'Unemployment rose sharply when the local coal mines closed.', '当地煤矿关闭后,失业率急剧上升。', 'Unemployment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('e-commerce-1', 'e-commerce', 'The growth of e-commerce has led to the closure of many high street shops.', '电子商务的发展导致许多商业街店铺关闭。', 'e-commerce');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('deficit-1', 'deficit', 'The government plans to reduce its budget deficit by cutting spending.', '政府计划通过削减开支来减少预算赤字。', 'deficit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('levy-1', 'levy', 'The new levy on plastic bags has greatly reduced their use.', '新的塑料袋税大大减少了它们的使用。', 'levy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('levy-2', 'levy', 'The king tried to levy a new tax to pay for the war.', '国王试图征收一种新税来支付战争费用。', 'levy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('quota-1', 'quota', 'Fishing boats must not catch more than their annual quota of cod.', '渔船捕捞的鳕鱼不得超过年度配额。', 'quota');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ration-1', 'ration', 'The weekly ration of meat was very small during the war.', '战争期间,每周的肉类配给量很少。', 'ration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('ration-2', 'ration', 'The government had to ration food for several years after the war.', '战后几年,政府不得不定量供应食品。', 'ration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('disburse-1', 'disburse', 'The fund will disburse money to farmers affected by the floods.', '这个基金将向受洪灾影响的农民拨款。', 'disburse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('fortune-1', 'fortune', 'He made a fortune from the sale of cotton in the 1850s.', '他在 19 世纪 50 年代靠卖棉花发了财。', 'fortune');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compensation-1', 'compensation', 'Families whose homes were destroyed received compensation from the government.', '房屋被毁的家庭获得了政府的补偿。', 'compensation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('depreciate-1', 'depreciate', 'New cars begin to depreciate as soon as they leave the factory.', '新车一出厂就开始贬值。', 'depreciate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('patronage-1', 'patronage', 'Wealthy families provided patronage for artists during the Renaissance.', '文艺复兴时期,富裕家族赞助了艺术家。', 'patronage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('endowment-1', 'endowment', 'The university''s large endowment pays for scholarships and new research.', '这所大学的巨额捐赠基金用于支付奖学金和新研究。', 'endowment');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('prosperous-1', 'prosperous', 'The town became prosperous through its trade in wool.', '这座城镇通过羊毛贸易变得繁荣起来。', 'prosperous');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('profitable-1', 'profitable', 'The new product line has proved highly profitable for the company.', '事实证明,新产品线为公司带来了丰厚的利润。', 'profitable');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sweatshop-1', 'sweatshop', 'Workers in the sweatshop sewed clothes for very low wages.', '血汗工厂的工人以极低的工资缝制衣服。', 'sweatshop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('merchant-1', 'merchant', 'A wealthy merchant paid for the construction of the town''s first hospital.', '一位富商出资修建了镇上第一家医院。', 'merchant');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('purchasing-power-1', 'purchasing-power', 'Rising prices have reduced the purchasing power of ordinary families.', '物价上涨降低了普通家庭的购买力。', 'purchasing power');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('joint-venture-1', 'joint-venture', 'The two companies formed a joint venture to build the new power station.', '这两家公司成立了一家合资企业来建造新发电站。', 'joint venture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('intellectual-property-1', 'intellectual-property', 'Stronger laws are needed to protect intellectual property on the internet.', '需要更严格的法律来保护互联网上的知识产权。', 'intellectual property');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('market-research-1', 'market-research', 'Market research showed that young people preferred the cheaper model.', '市场调研显示年轻人更喜欢较便宜的型号。', 'Market research');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('advertising-campaign-1', 'advertising-campaign', 'The advertising campaign increased sales by more than twenty percent.', '这次广告宣传活动使销售额增长了百分之二十多。', 'advertising campaign');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('monetary-1', 'monetary', 'The central bank controls the country''s monetary policy.', '中央银行控制着国家的货币政策。', 'monetary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('barrel-1', 'barrel', 'The price of oil rose above one hundred dollars a barrel.', '石油价格涨到了每桶一百多美元。', 'barrel');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gross-1', 'gross', 'The gross income of the company reached ten million dollars last year.', '这家公司去年的总收入达到一千万美元。', 'gross');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('auction-1', 'auction', 'The painting was sold at auction for over a million pounds.', '这幅画在拍卖会上以一百多万英镑售出。', 'auction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('auction-2', 'auction', 'The government decided to auction the rights to use the radio frequencies.', '政府决定拍卖无线电频率的使用权。', 'auction');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('surplus-1', 'surplus', 'Countries with a food surplus can sell the extra to their neighbours.', '粮食过剩的国家可以把多余的卖给邻国。', 'surplus');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overhead-1', 'overhead', 'Lower overheads allow online shops to sell goods at cheaper prices.', '较低的经常性开支让网店能以更便宜的价格销售商品。', 'overheads');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('overhead-2', 'overhead', 'Overhead power lines are being replaced by underground cables.', '头顶上的电线正在被地下电缆取代。', 'Overhead');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nominal-1', 'nominal', 'Visitors pay only a nominal charge to enter the small museum.', '参观这座小博物馆只需支付象征性的费用。', 'nominal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('venture-1', 'venture', 'Her first business venture failed, but she learned a great deal from it.', '她第一次创业失败了,但从中学到了很多。', 'venture');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equity-1', 'equity', 'The bank agreed to provide equity for the new company.', '银行同意为这家新公司提供股本。', 'equity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('equity-2', 'equity', 'The aim of the policy is to bring greater equity in health care.', '这项政策的目标是在医疗保健方面实现更大的公平。', 'equity');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('stake-1', 'stake', 'The government still holds a large stake in the national airline.', '政府仍持有这家国家航空公司的大量股份。', 'stake');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('tender-1', 'tender', 'Companies were invited to submit a tender for building the new bridge.', '公司受邀就建造新桥提交投标。', 'tender');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('affiliate-1', 'affiliate', 'The local radio station is an affiliate of a national network.', '这家地方电台是一家全国性广播网的附属机构。', 'affiliate');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('lucrative-1', 'lucrative', 'The trade in spices was extremely lucrative for European merchants.', '香料贸易对欧洲商人来说利润极高。', 'lucrative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('warehouse-1', 'warehouse', 'The goods are stored in a large warehouse beside the motorway.', '这些货物存放在高速公路旁的一个大仓库里。', 'warehouse');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('textile-1', 'textile', 'The textile industry brought great wealth to northern England.', '纺织业给英格兰北部带来了巨大财富。', 'textile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embargo-1', 'embargo', 'The oil embargo of 1973 caused prices to rise dramatically.', '1973 年的石油禁运导致油价急剧上涨。', 'embargo');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('technology-1', 'technology', 'New technology has changed the way that people work and study.', '新技术改变了人们的工作和学习方式。', 'technology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('technological-1', 'technological', 'Rapid technological change has made many traditional jobs disappear.', '快速的技术变革使许多传统工作消失了。', 'technological');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('innovation-1', 'innovation', 'Innovation is essential if small companies are to survive.', '小公司要想生存,创新至关重要。', 'Innovation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('innovative-1', 'innovative', 'The company is known for its innovative approach to reducing waste.', '这家公司以创新的减废方法闻名。', 'innovative');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('breakthrough-1', 'breakthrough', 'The discovery of penicillin was a major breakthrough in the treatment of infection.', '青霉素的发现是治疗感染方面的重大突破。', 'breakthrough');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cutting-edge-1', 'cutting-edge', 'The laboratory uses cutting-edge equipment to study the structure of cells.', '实验室使用尖端设备研究细胞结构。', 'cutting-edge');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('state-of-the-art-1', 'state-of-the-art', 'The new hospital has state-of-the-art equipment for treating heart disease.', '新医院拥有治疗心脏病的最先进设备。', 'state-of-the-art');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('artificial-intelligence-1', 'artificial-intelligence', 'Artificial intelligence is now being used to help doctors identify diseases.', '人工智能现在被用来帮助医生识别疾病。', 'Artificial intelligence');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('algorithm-1', 'algorithm', 'The algorithm learns to recognise faces from millions of photographs.', '这种算法从数百万张照片中学习识别人脸。', 'algorithm');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('automation-1', 'automation', 'Automation may replace many routine jobs in the coming decades.', '未来几十年,自动化可能取代许多重复性工作。', 'Automation');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('robot-1', 'robot', 'A robot can now perform some kinds of surgery with great accuracy.', '现在机器人能高度精确地完成某些类型的手术。', 'robot');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('robotics-1', 'robotics', 'Advances in robotics have transformed the way cars are built.', '机器人学的进步改变了汽车的制造方式。', 'robotics');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('digital-1', 'digital', 'Digital technology has made it easy to store and share photographs.', '数字技术让存储和分享照片变得很容易。', 'Digital');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('software-1', 'software', 'The new software can translate speech into text almost immediately.', '新软件几乎能立刻把语音转成文字。', 'software');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hardware-1', 'hardware', 'Older computer hardware cannot run the latest versions of the program.', '旧的计算机硬件无法运行最新版本的程序。', 'hardware');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('processor-1', 'processor', 'A faster processor allows the phone to run several programs at once.', '更快的处理器让手机能同时运行多个程序。', 'processor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('chip-1', 'chip', 'The tiny chip contains billions of electronic parts.', '这块小芯片包含数十亿个电子元件。', 'chip');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('network-1', 'network', 'The company has built a network of charging points across the country.', '这家公司在全国建立了充电站网络。', 'network');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('online-1', 'online', 'More than half of all purchases in the country are now made online.', '该国现在有一半以上的购买是在网上进行的。', 'online');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('browser-1', 'browser', 'Each browser stores information about the websites that users visit.', '每个浏览器都会存储用户访问网站的信息。', 'browser');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('server-1', 'server', 'Information is stored on a server that may be far from the user.', '信息存储在可能离用户很远的服务器上。', 'server');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cyberspace-1', 'cyberspace', 'Governments find it hard to enforce their laws in cyberspace.', '政府发现很难在网络空间执法。', 'cyberspace');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cybercrime-1', 'cybercrime', 'Cybercrime costs businesses billions of pounds in lost money each year.', '网络犯罪每年使企业损失数十亿英镑。', 'Cybercrime');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('hacker-1', 'hacker', 'A hacker stole the personal details of thousands of customers.', '一名黑客窃取了数千名客户的个人信息。', 'hacker');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('privacy-1', 'privacy', 'Many people worry about their privacy when they use social media.', '许多人使用社交媒体时担心隐私问题。', 'privacy');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('security-1', 'security', 'Banks have spent large sums on improving the security of online payments.', '银行投入大量资金提高在线支付的安全。', 'security');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('encryption-1', 'encryption', 'Encryption protects messages from being read by anyone except the receiver.', '加密保护信息不被接收者以外的任何人读取。', 'Encryption');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('big-data-1', 'big-data', 'Companies use big data to predict what their customers will buy next.', '公司利用大数据预测顾客接下来会买什么。', 'big data');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cloud-computing-1', 'cloud-computing', 'Cloud computing allows small firms to store data at a low cost.', '云计算让小公司能以低成本存储数据。', 'Cloud computing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('virtual-reality-1', 'virtual-reality', 'Medical students can practise operations safely using virtual reality.', '医学生可以利用虚拟现实安全地练习手术。', 'virtual reality');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('smartphone-1', 'smartphone', 'The smartphone has changed the way people find information and communicate.', '智能手机改变了人们获取信息和交流的方式。', 'smartphone');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('gadget-1', 'gadget', 'This small gadget measures how many steps you take each day.', '这个小装置记录你每天走了多少步。', 'gadget');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('app-1', 'app', 'A new app helps patients to remember when to take their medicine.', '一款新应用程序帮助患者记住服药时间。', 'app');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('interface-1', 'interface', 'The simple interface of the program makes it easy for older people to use.', '这个程序简单的界面让老年人也能轻松使用。', 'interface');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('user-friendly-1', 'user-friendly', 'The designers have tried to make the system more user-friendly.', '设计者努力让这个系统更便于用户使用。', 'user-friendly');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('compatible-1', 'compatible', 'The new software is not compatible with older types of computer.', '新软件与旧型号的计算机不兼容。', 'compatible');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('upgrade-1', 'upgrade', 'The city plans to upgrade its old water pipes over the next ten years.', '这座城市计划在未来十年升级老旧水管。', 'upgrade');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('obsolete-1', 'obsolete', 'Many skills have become obsolete because of developments in technology.', '由于技术发展,许多技能已被淘汰。', 'obsolete');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('outdated-1', 'outdated', 'Much of the country''s railway system is now outdated and slow.', '该国大部分铁路系统现在已经过时,而且速度缓慢。', 'outdated');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('telecommunication-1', 'telecommunication', 'Telecommunication satellites allow people to make calls from remote areas.', '电信卫星让人们能在偏远地区打电话。', 'Telecommunication');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('broadband-1', 'broadband', 'Fast broadband is still unavailable in many remote rural villages.', '许多偏远农村仍然用不上高速宽带。', 'broadband');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('wireless-1', 'wireless', 'Wireless technology allows farmers to monitor their fields from their phones.', '无线技术让农民能用手机监控农田。', 'Wireless');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('signal-1', 'signal', 'The satellite sends a signal back to Earth every few minutes.', '这颗卫星每隔几分钟向地球发回一次信号。', 'signal');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('sensor-1', 'sensor', 'A sensor in the soil tells the farmer when the plants need water.', '土壤中的传感器告诉农民植物何时需要浇水。', 'sensor');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('3d-printing-1', '3d-printing', '3D printing allows engineers to produce complex parts at a low cost.', '3D 打印让工程师能以低成本制造复杂的零件。', '3D printing');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('nanotechnology-1', 'nanotechnology', 'Nanotechnology may one day allow doctors to deliver drugs directly to cells.', '有朝一日,纳米技术可能让医生把药物直接送到细胞。', 'Nanotechnology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('biotechnology-1', 'biotechnology', 'Advances in biotechnology have produced crops that can resist disease.', '生物技术的进步培育出了能抵抗疾病的作物。', 'biotechnology');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('genetic-engineering-1', 'genetic-engineering', 'Genetic engineering could be used to make crops more resistant to drought.', '基因工程可用于增强作物的抗旱能力。', 'Genetic engineering');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('cloning-1', 'cloning', 'The cloning of a sheep in 1996 caused great public debate.', '1996 年克隆羊引发了公众的激烈争论。', 'cloning');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('virtual-1', 'virtual', 'Students can now take a virtual tour of the museum on the internet.', '学生现在可以在网上虚拟参观博物馆。', 'virtual');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('automatic-1', 'automatic', 'Automatic doors allow people to enter the building without using their hands.', '自动门让人们不用手就能进入大楼。', 'Automatic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('electronic-1', 'electronic', 'Electronic books have become popular, but printed books are still selling well.', '电子书已经流行起来,但纸质书依然卖得很好。', 'Electronic');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transmission-1', 'transmission', 'Rapid transmission of the virus occurs in crowded places.', '这种病毒在拥挤的地方传播迅速。', 'transmission');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('loop-1', 'loop', 'A feedback loop can make global warming happen more quickly.', '反馈循环可能使全球变暖加快。', 'loop');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('protocol-1', 'protocol', 'Every doctor must follow a strict safety protocol when handling the virus.', '每位医生处理这种病毒时都必须遵守严格的安全规程。', 'protocol');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('transmit-1', 'transmit', 'Mosquitoes can transmit the disease from one person to another.', '蚊子能把这种疾病从一个人传给另一个人。', 'transmit');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('configuration-1', 'configuration', 'The configuration of the seats can be changed for different events.', '座位的配置可以根据不同活动调整。', 'configuration');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('node-1', 'node', 'Each node in the network passes information on to the next.', '网络中的每个节点把信息传递给下一个节点。', 'node');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('binary-1', 'binary', 'Computers store all their information in binary code using ones and zeros.', '计算机用由一和零组成的二进制代码存储所有信息。', 'binary');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('erase-1', 'erase', 'It is almost impossible to erase information completely from the internet.', '几乎不可能从互联网上彻底删除信息。', 'erase');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('audio-1', 'audio', 'The museum provides audio guides in more than twenty languages.', '博物馆提供二十多种语言的音频导览。', 'audio');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('embed-1', 'embed', 'Scientists hope to embed tiny sensors in the walls of new buildings.', '科学家希望把微型传感器嵌入新建筑的墙壁。', 'embed');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('web-1', 'web', 'The growth of the web has changed how scientists share their research.', '互联网的发展改变了科学家分享研究成果的方式。', 'web');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('mobile-1', 'mobile', 'Mobile phones have made banking possible in many remote areas.', '手机让许多偏远地区也能使用银行服务。', 'Mobile');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('storage-1', 'storage', 'Cheap storage of electricity remains the main challenge for solar power.', '廉价储电仍是太阳能面临的主要挑战。', 'storage');
INSERT INTO ielts_examples (id, word_id, sentence_en, sentence_zh, target) VALUES ('delete-1', 'delete', 'Users can delete their personal data from the website at any time.', '用户可以随时从网站上删除个人数据。', 'delete');
